#!/usr/bin/env bash
set -euo pipefail

export PATH="${HOME}/.local/bin:/home/digit/.npm-global/bin:${HOME}/.npm-global/bin:$PATH"

if ! mountpoint -q /mnt/c || [ ! -d /mnt/c/Users/digit/Dropbox ]; then
  echo "[baselane-monthly] Dropbox mount unavailable at /mnt/c/Users/digit/Dropbox" >&2
  exit 75
fi

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT="${WORKSPACE_ROOT:-$(cd "$SCRIPT_DIR/.." && pwd)}"
MONTHLY_DISCORD_CODE_ROOT="${BASELANE_MONTHLY_DISCORD_CODE_ROOT:-$ROOT}"
OPENCLAW_ROOT="${OPENCLAW_ROOT:-$(cd "$ROOT/.." && pwd)}"
PY="${PYTHON_BIN:-python3}"
BASELANE_CANONICAL_CRONTAB_FILE="${BASELANE_CANONICAL_CRONTAB_FILE:-$ROOT/config/openclaw-wsl-worker.crontab}"
BASELANE_MONTHLY_SYSTEMD_TIMER_FILE="${BASELANE_MONTHLY_SYSTEMD_TIMER_FILE:-$HOME/.config/systemd/user/baselane-financials-monthly.timer}"

BASELANE_MONTHLY_LOCK_PATH="${BASELANE_MONTHLY_LOCK_PATH:-/home/digit/.cache/openclaw-locks/baselane-monthly-v2.lock}"
BASELANE_MONTHLY_SKIP_SELF_LOCK="${BASELANE_MONTHLY_SKIP_SELF_LOCK:-0}"

baselane_monthly_parent_holds_lock() {
  local pid="${PPID:-}"
  local args=""
  local stat_line=""
  local parent=""
  local hop_count=0
  local -a stat_fields=()
  while [ -n "$pid" ] && [ "$pid" != "1" ] && [ "$hop_count" -lt 16 ]; do
    if [ -r "/proc/$pid/cmdline" ]; then
      args="$(tr '\0' ' ' < "/proc/$pid/cmdline" 2>/dev/null || true)"
    else
      args=""
    fi
    if printf '%s\n' "$args" | grep -Fq "$BASELANE_MONTHLY_LOCK_PATH"; then
      return 0
    fi
    if [ -r "/proc/$pid/stat" ]; then
      stat_line="$(cat "/proc/$pid/stat" 2>/dev/null || true)"
    else
      stat_line=""
    fi
    stat_line="${stat_line#*) }"
    read -r -a stat_fields <<< "$stat_line"
    parent="${stat_fields[1]:-}"
    if [ -z "$parent" ] || [ "$parent" = "$pid" ]; then
      break
    fi
    pid="$parent"
    hop_count=$((hop_count + 1))
  done
  return 1
}

if [ "$BASELANE_MONTHLY_SKIP_SELF_LOCK" != "1" ] && ! baselane_monthly_parent_holds_lock; then
  mkdir -p "$(dirname "$BASELANE_MONTHLY_LOCK_PATH")"
  export BASELANE_MONTHLY_SKIP_SELF_LOCK=1
  flock -n -E 75 "$BASELANE_MONTHLY_LOCK_PATH" "$0" "$@"
  rc=$?
  if [ "$rc" -eq 75 ]; then
    echo "[baselane-monthly] another monthly Baselane/Lofty run already holds $BASELANE_MONTHLY_LOCK_PATH" >&2
    exit 75
  fi
  exit "$rc"
else
  export BASELANE_MONTHLY_SELF_LOCK_STATUS="inherited_or_skipped"
fi

case "$PY" in
  "/usr/bin/env python3"|"env python3") PY="python3" ;;
esac
if ! "$PY" -c 'import openpyxl' >/dev/null 2>&1; then
  for candidate in /home/linuxbrew/.linuxbrew/bin/python3 /home/linuxbrew/.linuxbrew/opt/python@3.14/bin/python3.14; do
    if [ -x "$candidate" ] && "$candidate" -c 'import openpyxl' >/dev/null 2>&1; then
      PY="$candidate"
      break
    fi
  done
fi
if ! "$PY" -c 'import openpyxl' >/dev/null 2>&1; then
  echo "[baselane-monthly] no Python interpreter with openpyxl is available" >&2
  exit 1
fi

DEFAULT_RUN_MONTH="$($PY - <<'PY'
from datetime import date

today = date.today()
year = today.year
month = today.month - 1
if month == 0:
    year -= 1
    month = 12
print(f"{year:04d}-{month:02d}")
PY
)"
