promote_source_cash_manifest() {
  "$PY" - "$DAILY_SOURCE_CASH_BALANCE_REPORT_FILE" "$DAILY_SOURCE_CASH_CF_MANIFEST_FILE" <<'PY'
import json
import os
import sys
from pathlib import Path

source, target = map(Path, sys.argv[1:])
payload = json.loads(source.read_text(encoding="utf-8"))
records = payload.get("checked_workbooks") or []
if int(payload.get("checked_workbook_count") or 0) != len(records):
    raise SystemExit(2)
if int(payload.get("unreadable_count") or 0) or int(payload.get("missing_row_count") or 0):
    raise SystemExit(2)
target.parent.mkdir(parents=True, exist_ok=True)
tmp = target.with_suffix(target.suffix + ".tmp")
tmp.write_text(json.dumps(payload, indent=2, sort_keys=True) + "\n", encoding="utf-8")
os.replace(tmp, target)
PY
}
# Closed CF columns must use the property GL through the target month-end.
# Current-control jobs outside this close retain their full_column_e default,
# and the Yhome current view is explicitly kept in full_column_e mode.
MONTHLY_SOURCE_CASH_MODE="${BASELANE_MONTHLY_SOURCE_CASH_MODE:-as_of_month_end}"
case "$MONTHLY_SOURCE_CASH_MODE" in
  full_column_e|as_of_month_end) ;;
  *)
    echo "[baselane-monthly] invalid BASELANE_MONTHLY_SOURCE_CASH_MODE: $MONTHLY_SOURCE_CASH_MODE" >&2
    exit 2
    ;;
esac
