fetch_yhome_sold_guard() {
  if [ "$YHOME_SOLD_GUARD_STATUS" = "ok" ]; then
    return 0
  fi
  if command -v gws >/dev/null 2>&1 && [ -n "$YHOME_GWS_SPREADSHEET_ID" ] && [ -f "$YHOME_TRANSITION_RECONCILIATION_SNAPSHOT_SCRIPT" ]; then
    local snapshot_args=()
    local sheet_spec
    IFS='|' read -ra sheet_specs <<< "$YHOME_GWS_SHEET_SPECS"
    for sheet_spec in "${sheet_specs[@]}"; do
      snapshot_args+=(--sheet "$sheet_spec")
    done
    if "$PY" "$YHOME_TRANSITION_RECONCILIATION_SNAPSHOT_SCRIPT" \
      --spreadsheet-id "$YHOME_GWS_SPREADSHEET_ID" \
      --output "$YHOME_TRANSITION_RECONCILIATION_CSV" \
      --report "$REPORT_DIR/yhome_transition_reconciliation_snapshot.json" \
      "${snapshot_args[@]}" >/dev/null 2>&1; then
      YHOME_SOLD_GUARD_STATUS="ok"
      return 0
    fi
    YHOME_SOLD_GUARD_STATUS="failed_multi_tab_snapshot"
    return 1
  fi
  if [ -n "$YHOME_TRANSITION_RECONCILIATION_URL" ]; then
    mkdir -p "$(dirname "$YHOME_TRANSITION_RECONCILIATION_CSV")"
    set +e
    curl -L --fail --silent --show-error "$YHOME_TRANSITION_RECONCILIATION_URL" -o "$YHOME_TRANSITION_RECONCILIATION_CSV"
    yhome_curl_rc="$?"
    set -e
    if [ "$yhome_curl_rc" -eq 0 ] && [ -s "$YHOME_TRANSITION_RECONCILIATION_CSV" ]; then
      YHOME_SOLD_GUARD_STATUS="ok"
    else
      YHOME_SOLD_GUARD_STATUS="failed_fetch"
    fi
  elif [ -s "$YHOME_TRANSITION_RECONCILIATION_CSV" ]; then
    YHOME_SOLD_GUARD_STATUS="ok"
  else
    YHOME_SOLD_GUARD_STATUS="not_configured"
  fi
}

extract_owner_email_packet_fields() {
  if [ -f "$OWNER_EMAIL_PACKET_FILE" ]; then
    IFS=$'\t' read -r \
      OWNER_EMAIL_PACKET_STATUS_FROM_REPORT \
      OWNER_EMAIL_PACKET_ISSUE_COUNT \
      OWNER_EMAIL_PACKET_PROPERTY_UNAVAILABLE_COUNT \
      OWNER_EMAIL_PACKET_RECIPIENT_COUNT \
      OWNER_EMAIL_PACKET_COUNT \
      OWNER_EMAIL_PACKET_FULL_HISTORY_LEAK_COUNT \
      OWNER_EMAIL_PACKET_BODY_GUARD_ISSUE_COUNT \
      OWNER_EMAIL_PACKET_NATIVE_PROPERTY_COUNT \
      OWNER_EMAIL_PACKET_NATIVE_PROPERTY_COVERAGE_OK \
      OWNER_EMAIL_PACKET_SAFE_TO_SEND_NOW \
      OWNER_EMAIL_PACKET_SENT_STATE_WRITTEN < <(
        $PY - "$OWNER_EMAIL_PACKET_FILE" <<'PY'
import json
import sys
from pathlib import Path

try:
    data = json.loads(Path(sys.argv[1]).read_text(encoding="utf-8"))
except Exception:
    data = {}
fields = (
    "status",
    "issue_count",
    "property_unavailable_count",
    "recipient_count",
    "packet_count",
    "full_history_leak_count",
    "body_guard_issue_count",
    "native_lofty_owner_email_property_count",
)
values = [str(data.get("status") or "")]
values.extend(str(int(data.get(field) or 0)) for field in fields[1:])
values.append("1" if data.get("native_lofty_owner_email_property_coverage_ok") is True else "0")
values.append("1" if data.get("safe_to_send_now") is True else "0")
values.append("1" if data.get("sent_state_written") is True else "0")
print("\t".join(values))
PY
      )
    if [ -n "$OWNER_EMAIL_PACKET_STATUS_FROM_REPORT" ]; then
      OWNER_EMAIL_PACKET_STATUS="$OWNER_EMAIL_PACKET_STATUS_FROM_REPORT"
    fi
  fi
}

run_non_native_owner_email_packet() {
  local packet_mode="${1:-dry-run}"
  OWNER_EMAIL_PACKET_SCRIPT="$ROOT/scripts/lofty_monthly_owner_email_packet.py"
  if [ ! -f "$OWNER_EMAIL_PACKET_SCRIPT" ]; then
    OWNER_EMAIL_PACKET_STATUS="skipped_missing_script"
    return 0
  fi

  OWNER_EMAIL_PACKET_ARGS=(
    --runtime-map "$LOFTY_PM_RUNTIME_MAP"
    --run-month "$RUN_MONTH"
    --sent-state-file "$OWNER_EMAIL_PACKET_SENT_STATE_FILE"
    --out-dir "$OWNER_EMAIL_PACKET_PREVIEW_DIR"
    --report "$OWNER_EMAIL_PACKET_FILE"
    --live-update-capture-report "$LIVE_UPDATE_CAPTURE_FILE"
    --listing-cleanup-queue-report "$LOFTY_LISTING_CLEANUP_QUEUE_FILE"
    --review-candidate-packet-report "$OWNER_EMAIL_PACKET_REVIEW_CANDIDATE_FILE"
    --discord-send-report "$MONTHLY_DISCORD_PROPERTY_UPDATE_SEND_FILE"
    --discord-plan-validation-report "$MONTHLY_DISCORD_ALL_SEND_PLAN_VALIDATION_FILE"
    --guild-test-post-report "$GUILD_TEST_POST_REPORT_FILE"
  )
  if [ "$SEND_NON_NATIVE_OWNER_EMAILS" = "1" ]; then
    OWNER_EMAIL_PACKET_ARGS+=(--recipients-csv "$OWNER_EMAIL_RECIPIENTS_CSV")
  else
    OWNER_EMAIL_PACKET_ARGS+=(--native-only)
  fi
  if [ "$packet_mode" = "send" ]; then
    OWNER_EMAIL_PACKET_ARGS+=(--send)
  else
    OWNER_EMAIL_PACKET_ARGS+=(--dry-run)
  fi

  set +e
  $PY "$OWNER_EMAIL_PACKET_SCRIPT" "${OWNER_EMAIL_PACKET_ARGS[@]}" >/dev/null
  owner_email_packet_rc="$?"
  set -e
  if [ "$owner_email_packet_rc" -eq 0 ]; then
    OWNER_EMAIL_PACKET_STATUS="ok"
  elif [ "$owner_email_packet_rc" -eq 2 ]; then
    OWNER_EMAIL_PACKET_STATUS="review"
    if [ "$packet_mode" = "send" ]; then
      exit "$owner_email_packet_rc"
    fi
  else
    OWNER_EMAIL_PACKET_STATUS="failed"
    exit "$owner_email_packet_rc"
  fi
  extract_owner_email_packet_fields
}

refresh_owner_email_send_guard_report() {
  OWNER_EMAIL_SEND_GUARD_SCRIPT="$ROOT/scripts/baselane_owner_email_send_guard.py"
  if [ -f "$OWNER_EMAIL_SEND_GUARD_SCRIPT" ]; then
    set +e
    $PY "$OWNER_EMAIL_SEND_GUARD_SCRIPT" \
      --root "$ROOT" \
      --readiness-report "$READINESS_FILE" \
      --publish-report "$LOFTY_PM_PUBLISH_FILE" \
