      --guild-test-post-report "$GUILD_TEST_POST_REPORT_FILE" \
      --report "$OWNER_EMAIL_SEND_GUARD_FILE" >/dev/null
    owner_email_send_guard_rc="$?"
    set -e
    if [ "$owner_email_send_guard_rc" -eq 0 ]; then
      OWNER_EMAIL_SEND_GUARD_STATUS="ok"
    elif [ "$owner_email_send_guard_rc" -eq 2 ]; then
      OWNER_EMAIL_SEND_GUARD_STATUS="review"
    else
      OWNER_EMAIL_SEND_GUARD_STATUS="failed"
      exit "$owner_email_send_guard_rc"
    fi
  else
    OWNER_EMAIL_SEND_GUARD_STATUS="skipped_missing_script"
  fi
  if [ -f "$OWNER_EMAIL_SEND_GUARD_FILE" ]; then
    IFS=$'\t' read -r \
      OWNER_EMAIL_SEND_GUARD_SEND_ALLOWED \
      OWNER_EMAIL_SEND_GUARD_SAFE_BLOCK \
      OWNER_EMAIL_SEND_GUARD_NO_SPAM_OK < <(
        $PY - "$OWNER_EMAIL_SEND_GUARD_FILE" <<'PY'
import json
import sys
from pathlib import Path

try:
    data = json.loads(Path(sys.argv[1]).read_text(encoding="utf-8"))
except Exception:
    data = {}
fields = ("send_allowed", "safe_block", "no_spam_guard_ok")
print("\t".join("1" if data.get(field) is True else "0" for field in fields))
PY
      )
  fi
}

refresh_monthly_readiness_report() {
  READINESS_SCRIPT="$ROOT/scripts/baselane_monthly_readiness_report.py"
  if [ -f "$READINESS_SCRIPT" ]; then
    set +e
    $PY "$READINESS_SCRIPT" \
      --root "$ROOT" \
      --report "$READINESS_FILE" \
      --markdown "$READINESS_MARKDOWN_FILE" \
      --current-run-started-at "$RUN_STARTED_AT" >/dev/null
    readiness_rc="$?"
    set -e
    if [ "$readiness_rc" -eq 0 ]; then
      MONTHLY_READINESS_STATUS="ok"
    elif [ "$readiness_rc" -eq 2 ]; then
      MONTHLY_READINESS_STATUS="review"
    else
      exit "$readiness_rc"
    fi
  else
    MONTHLY_READINESS_STATUS="skipped_missing_script"
  fi

  if [ -f "$READINESS_FILE" ]; then
    IFS=$'\t' read -r MONTHLY_READINESS_OWNER_EMAIL_ALLOWED MONTHLY_READINESS_BLOCKER_COUNT MONTHLY_READINESS_ACTIONABLE_BLOCKER_COUNT MONTHLY_READINESS_PRIMARY_BLOCKER < <(
      $PY - "$READINESS_FILE" <<'PY'
import json
import sys
from pathlib import Path

try:
    data = json.loads(Path(sys.argv[1]).read_text(encoding="utf-8"))
except Exception:
    data = {}
allowed = "1" if data.get("owner_email_allowed") is True else "0"
blockers = int(data.get("blocker_count") or 0)
actionable = data.get("actionable_summary") if isinstance(data.get("actionable_summary"), dict) else {}
primary = actionable.get("primary_blocker") if isinstance(actionable.get("primary_blocker"), dict) else {}
actionable_count = int(actionable.get("actionable_blocker_count") or 0)
primary_text = str(primary.get("blocker") or primary.get("class") or "").replace("\t", " ").replace("\n", " ").strip()
print(f"{allowed}\t{blockers}\t{actionable_count}\t{primary_text}")
PY
    )
  fi
  MONTHLY_FINANCIAL_CORRECTIVE_PUBLISH_ALLOWED="0"
  if [ -f "$READINESS_FILE" ] && [ -f "$LOFTY_FINANCIAL_PATCH_READINESS_FILE" ]; then
    MONTHLY_FINANCIAL_CORRECTIVE_PUBLISH_ALLOWED="$($PY - "$READINESS_FILE" "$LOFTY_FINANCIAL_PATCH_READINESS_FILE" <<'PY'
import json
import sys
from pathlib import Path

def read_json(path: str) -> dict:
    try:
        return json.loads(Path(path).read_text(encoding="utf-8"))
    except Exception:
        return {}

readiness = read_json(sys.argv[1])
patch = read_json(sys.argv[2])
primary = readiness.get("primary_blocker") if isinstance(readiness.get("primary_blocker"), dict) else {}
if not primary and isinstance(readiness.get("actionable_summary"), dict):
    primary = readiness["actionable_summary"].get("primary_blocker") if isinstance(readiness["actionable_summary"].get("primary_blocker"), dict) else {}
primary_class = str(primary.get("class") or primary.get("blocker") or "").strip()
patch_status = str(patch.get("status") or "").strip()
ready = int(patch.get("ready_financial_patch_count") or 0)
blocked = int(patch.get("blocked_count") or 0)
fields = int(patch.get("field_count_total") or 0)
property_count = int(patch.get("property_count") or 0)
allowed = (
    primary_class == "live_financial_capture.review"
    and patch_status == "ok"
    and blocked == 0
    and fields > 0
    and ready >= max(property_count, 1)
)
print("1" if allowed else "0")
PY
)"
  fi
}

