import json
import hashlib
import os
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

def read_json(path_text):
    try:
        data = json.loads(Path(path_text).read_text(encoding="utf-8"))
    except Exception:
        return {}
    return data if isinstance(data, dict) else {}

def payload_digest(payload):
    return hashlib.sha256(json.dumps(payload, sort_keys=True, separators=(",", ":"), default=str).encode()).hexdigest()

def file_digest(path_text):
    try:
        return hashlib.sha256(Path(str(path_text)).read_bytes()).hexdigest()
    except Exception:
        return None

def sha256ish(value):
    return isinstance(value, str) and len(value) == 64 and all(char in "0123456789abcdef" for char in value.lower())

def iso_timestamp(value):
    text = str(value or "").strip()
    if not text:
        return None
    try:
        parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
    except ValueError:
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)

def generated_at_current_for_run(generated_at, started_at):
    generated = iso_timestamp(generated_at)
    started = iso_timestamp(started_at)
    if generated is None or started is None:
        return None
    return generated >= started

def preferred_value(primary, primary_key, fallback, fallback_key, default=None):
    if primary_key in primary:
        return primary.get(primary_key)
    if fallback_key in fallback:
        return fallback.get(fallback_key)
    return default

def monthly_disk_next_action(path_text):
    disk = read_json(path_text) if path_text else {}
    action = str(disk.get("next_action") or "").strip()
    if action:
        return f"{action} Then rerun scripts/baselane_cron_run.sh and monthly publish/email."
    return "Free local Dropbox/Windows disk space, rerun scripts/baselane_cron_run.sh, then rerun monthly publish/email."

MONTHLY_CHAIN_REQUIRED_ORDER = [
    "dao_vendor_upstream_normalization",
    "property_reconciliation_hold_refresh",
    "monthly_accruals_completeness",
    "cf_balance_sheet_consistency",
    "yhome_operating_cash_apply_verify",
    "quitman_804_cash_alignment",
    "source_cash_reconciliation_actions",
    "transfer_reconciliation",
    "transfer_reconciliation_telegram",
    "monthly_readiness_report_post_reconciliation",
    "discord_all_send_plan",
    "discord_review_drafts",
    "lofty_pm_publish",
    "lofty_live_updates_full_local_restore",
    "lofty_live_updates_history_containment",
    "lofty_financial_patch_readiness",
    "discord_property_update",
    "non_native_owner_email_packet",
    "monthly_pipeline_candidate_coverage",
    "owner_email_send_guard",
    "non_native_owner_email_packet_send",
    "owner_email_diagnostic",
    "owner_email_send",
]

def monthly_chain_ordering(script_text):
    positions = {}
    missing = []
    for step in MONTHLY_CHAIN_REQUIRED_ORDER:
        marker = f'CURRENT_STEP="{step}"'
        position = script_text.find(marker)
        positions[step] = position if position >= 0 else None
        if position < 0:
            missing.append(step)
    order_issues = [
        {
            "before": before,
            "after": after,
            "before_position": positions.get(before),
            "after_position": positions.get(after),
        }
        for before, after in zip(MONTHLY_CHAIN_REQUIRED_ORDER, MONTHLY_CHAIN_REQUIRED_ORDER[1:])
        if positions.get(before) is None
        or positions.get(after) is None
        or int(positions.get(before) or -1) >= int(positions.get(after) or -1)
    ]
    return {
        "status": "ok" if not missing and not order_issues else "review",
        "required_order": MONTHLY_CHAIN_REQUIRED_ORDER,
        "positions": positions,
        "missing_steps": missing,
        "order_issue_count": len(order_issues),
        "order_issues": order_issues,
        "policy": "Monthly transfer Telegram runs after CF/source sync and before Discord review; Lofty publish and financial patch readiness run before Discord posts; Discord review runs before owner email guard/send; owner email is final.",
    }

