    canonical_crontab_text = ""
canonical_crontab_schedule_ok = any(
    line.strip()
    and not line.lstrip().startswith("#")
    and line.startswith("0 3 15 * * ")
    and "flock -n" in line
    and "timeout" in line
    and "baselane_financials_monthly_cron.sh" in line
    for line in canonical_crontab_text.splitlines()
)
