except (OSError, UnicodeError):
    systemd_timer_text = ""
systemd_timer_values = {}
in_timer_section = False
for raw_line in systemd_timer_text.splitlines():
    line = raw_line.strip()
    if line.startswith("[") and line.endswith("]"):
        in_timer_section = line == "[Timer]"
        continue
    if in_timer_section and "=" in line and not line.startswith("#"):
        key, value = line.split("=", 1)
        systemd_timer_values[key.strip()] = value.strip()
systemd_monthly_timer_schedule_ok = (
    systemd_timer_values.get("OnCalendar", "").startswith("*-*-15 ")
