disk_preflight = read_json(report.get("disk_space_preflight_report") or "")
report["disk_space_preflight_next_action"] = str(disk_preflight.get("next_action") or "").strip() or None
report["disk_space_preflight_required_free_mib"] = disk_preflight.get("required_free_mib")
owner_email_final_financial_gate_ok = (
    report.get("owner_email_send_guard_email_final_gate_financial_blocked") is False
    and report.get("owner_email_send_guard_email_final_gate_discord_review_blocked") is False
    and report.get("owner_email_send_guard_email_final_gate_transfer_telegram_blocked") is False
    and report.get("owner_email_send_guard_transfer_telegram_send_gate_ok") is True
    and report.get("owner_email_send_guard_financial_review_blocker_count") == 0
    and not report.get("owner_email_send_guard_transfer_reconciliation_source_blockers")
    and not report.get("owner_email_send_guard_transfer_reconciliation_active_source_cash_actions")
    and not report.get("owner_email_send_guard_transfer_reconciliation_property_cash_review_details")
    and report.get("owner_email_send_guard_discord_financial_review_issue_count") == 0
)
monthly_live_final_send_deadline_gate_ok = (
    report.get("monthly_cron_schedule_ok") is True
    and report.get("monthly_live_send_window_ok") is True
    and report.get("monthly_readiness_owner_email_allowed") is True
    and report.get("owner_email_send_guard_send_allowed") is True
    and owner_email_final_financial_gate_ok
)
report["owner_email_final_financial_gate_ok"] = owner_email_final_financial_gate_ok
report["monthly_live_final_send_deadline_gate_ok"] = monthly_live_final_send_deadline_gate_ok
report["monthly_live_final_send_deadline_gate"] = {
    "ok": monthly_live_final_send_deadline_gate_ok,
    "cron_schedule_ok": report.get("monthly_cron_schedule_ok"),
    "live_send_window_ok": report.get("monthly_live_send_window_ok"),
    "readiness_owner_email_allowed": report.get("monthly_readiness_owner_email_allowed"),
    "owner_email_send_guard_send_allowed": report.get("owner_email_send_guard_send_allowed"),
    "owner_email_final_financial_gate_ok": owner_email_final_financial_gate_ok,
    "dry_run": report.get("dry_run"),
    "effective_send_owner_emails": report.get("effective_send_owner_emails"),
    "owner_email_send_blocked_reason": report.get("owner_email_send_blocked_reason"),
}
non_blocking_work_product_steps = {
    "yhome_operating_cash_apply_verify",
}
blocking_step_statuses = {
    name: status
    for name, status in report["steps"].items()
    if str(status or "").startswith(("failed", "review"))
    and name not in non_blocking_work_product_steps
}
report["non_blocking_work_product_steps"] = sorted(non_blocking_work_product_steps)
if (
    str(report["steps"].get("quitman_804_cash_alignment") or "").startswith(("failed", "review"))
    and transfer_reconciliation.get("status") == "ok"
    and int(transfer_reconciliation.get("property_cash_review_blocked_property_count") or 0) == 0
):
    report["steps"]["quitman_804_cash_alignment"] = "ok"
    blocking_step_statuses.pop("quitman_804_cash_alignment", None)
    report["quitman_804_cash_alignment_active_transfer_blocking_status"] = "ok"
if os.environ.get("DRY_RUN") != "1":
    aligned_scope_status = str(statements_idempotent.get("aligned_owner_scope_review_status") or "")
    aligned_downstream_status = str(statements_idempotent.get("aligned_owner_downstream_validation_status") or "")
    aligned_completion_gate_status = str(statements_idempotent.get("aligned_owner_completion_gate_status") or "")
    aligned_queue_active = statements_idempotent.get("aligned_owner_import_backfill_queue_active") is True
    aligned_queue_status = str(statements_idempotent.get("aligned_owner_import_backfill_queue_status") or "")
    aligned_queue_requires_completion = aligned_queue_active or aligned_queue_status == "queued"
    if aligned_queue_requires_completion:
        if aligned_completion_gate_status and aligned_completion_gate_status != "complete":
            blocking_step_statuses["aligned_owner_statement_import"] = aligned_completion_gate_status
        elif aligned_scope_status and aligned_scope_status != "ok":
            blocking_step_statuses["aligned_owner_statement_import"] = aligned_scope_status
        elif aligned_downstream_status and aligned_downstream_status != "ok":
            blocking_step_statuses["aligned_owner_statement_import"] = aligned_downstream_status
        elif not aligned_scope_status and not aligned_downstream_status:
            blocking_step_statuses["aligned_owner_statement_import"] = "review_missing_aligned_owner_validation"
if readiness.get("status") == "review" and "monthly_readiness" not in blocking_step_statuses:
    blocking_step_statuses["monthly_readiness"] = "review"
non_actionable_review_statuses = {"review_dry_run", "review_not_required"}
actionable_blocking_step_statuses = {
    name: status
    for name, status in blocking_step_statuses.items()
    if str(status or "") not in non_actionable_review_statuses
}
def evidence_item(name, ok, evidence=None, gap=None):
    item = {"name": name, "ok": bool(ok)}
    if evidence is not None:
        item["evidence"] = evidence
    if gap and not ok:
        item["gap"] = gap
    return item

def owner_email_packet_and_guard_ready_for_current_mode(report, dry_run):
    native_packet_ready = (
        report.get("owner_email_packet_status") == "ok"
        and report.get("owner_email_packet_native_property_coverage_ok") is True
        and int(report.get("owner_email_packet_issue_count") or 0) == 0
        and int(report.get("owner_email_packet_body_guard_issue_count") or 0) == 0
        and int(report.get("owner_email_packet_full_history_leak_count") or 0) == 0
        and int(report.get("owner_email_packet_native_property_count") or 0) > 0
    )
    guard_structurally_ready = (
        int(report.get("owner_email_send_guard_issue_count") or 0) == 0
        and report.get("owner_email_send_guard_no_spam_ok") is True
        and report.get("owner_email_send_guard_max_once_monthly_ok") is True
        and report.get("owner_email_send_guard_send_evidence_matches_intent") is True
        and (
            report.get("owner_email_send_guard_owner_email_packet_ok_for_send") is True
            or report.get("owner_email_send_guard_owner_email_packet_mcp_native_packet_ok") is True
            or native_packet_ready
        )
    )
    if not native_packet_ready or not guard_structurally_ready:
        return False
    if dry_run:
        return report.get("owner_email_send_guard_status") in {"ok", "review"}
    return (
        report.get("owner_email_send_guard_status") == "ok"
        and report.get("owner_email_status") == "sent_by_non_native_owner_email_packet"
        and report.get("owner_email_packet_sent_state_written") is True
        and int(report.get("owner_email_publish_send_evidence_issue_count") or 0) == 0
        and int(report.get("owner_email_publish_send_evidence_count") or 0)
        == int(report.get("owner_email_publish_will_send_count") or 0)
        and int(report.get("owner_email_publish_will_send_count") or 0) > 0
        and report.get("owner_email_send_guard_sent_state_file_matches_run_month") is True
    )

def retag_partial_ready_from_protected_blockers(report: dict[str, Any]) -> bool:
    full_blocked = int(report.get("baselane_85104_preclosing_retag_blocked_count") or 0)
    protected_blocked = int(report.get("baselane_85104_preclosing_retag_protected_closing_row_count") or 0)
    return (
        int(report.get("baselane_85104_preclosing_retag_partial_ready_count") or 0) > 0
        and int(report.get("baselane_85104_preclosing_retag_partial_unprotected_blocked_count") or 0) == 0
        and full_blocked > 0
        and full_blocked == protected_blocked
    )

def monthly_live_send_env_prefix(report: dict[str, Any], *, send_owner_emails: bool = False) -> str:
    run_month = str(report.get("run_month") or os.environ.get("RUN_MONTH") or "2026-06").strip() or "2026-06"
    parts = [
        f"RUN_MONTH={run_month}",
        "DRY_RUN=0",
        f"SEND_OWNER_EMAILS={'1' if send_owner_emails else '0'}",
    ]
    return " ".join(parts)

def live_lofty_publish_completion_command(report: dict[str, Any]) -> str:
    return (
        f"{monthly_live_send_env_prefix(report, send_owner_emails=False)} "
        "SEND_MONTHLY_DISCORD_PROPERTY_UPDATE=0 "
        "PUBLISH_LOFTY_PM_UPDATES=1 "
        "APPLY_LOFTY_GUARDED_UPDATES=1 "
        "RUN_LOFTY_GUARDED_APPLY=1 "
        "bash scripts/baselane_financials_monthly_cron.sh"
    )

def live_discord_property_update_command(report: dict[str, Any]) -> str:
    account = str(report.get("discord_property_update_discord_account_id") or "").strip()
    command = (
        "python3 scripts/run_monthly_discord_review_via_agent.py "
        "--plan reports/baselane_financials_monthly_discord_all_send_plan.json "
        "--report reports/baselane_financials_monthly_discord_review_drafts.json "
        "--agent-report reports/baselane_financials_monthly_discord_review_drafts_agent.json "
        "--sender-script scripts/send_monthly_discord_review_drafts.py "
        "--plan-validation reports/baselane_financials_monthly_discord_all_send_plan_validation.json "
        "--send"
    )
    if account:
        command += f" --account {account}"
    return command

def coownership_gl_policy_completion_action(report: dict[str, Any]) -> str:
    blocked_properties = [
        str(value).strip()
        for value in (report.get("coownership_gl_policy_validation_blocked_properties") or [])
        if str(value).strip()
    ]
    policy_action = "Resolve co-ownership GL policy issues"
    if blocked_properties:
        policy_action += f" for {', '.join(blocked_properties)}"

    retag_pending = (
        int(report.get("baselane_85104_preclosing_retag_payload_transaction_count") or 0) > 0
        or report.get("baselane_85104_preclosing_retag_apply_ready") is not True
    )
    if retag_pending:
        return (
            f"{policy_action}. Apply the prepared 85-104 pre-closing Baselane retag "
            "only after current digest and authentication preflight. Then rerun daily "
            "sync/split and co-ownership validation."
        )
    return f"{policy_action}. Rerun daily sync/split and co-ownership validation."

def blocker_preflight(report: dict[str, Any], name: str) -> dict[str, Any]:
    if name in {"coownership_gl_policy_validation", "coownership_prelaunch_gl_policy_and_85104_retag"}:
        blockers: list[str] = []
        partial_ready = retag_partial_ready_from_protected_blockers(report)
        partial_ack_env = str(
            report.get("baselane_85104_preclosing_retag_partial_apply_ack_env")
            or "BASELANE_85104_PRECLOSING_PARTIAL_WILL_NOT_CLEAR_VALIDATION"
        )
        full_blocked_count = int(report.get("baselane_85104_preclosing_retag_blocked_count") or 0)
        protected_blocked_count = int(report.get("baselane_85104_preclosing_retag_protected_closing_row_count") or 0)
        protected_review_status = str(
            report.get("baselane_85104_preclosing_retag_protected_closing_row_review_status") or ""
        )
        if report.get("baselane_85104_preclosing_retag_apply_ready") is not True:
            blockers.append("baselane_85104_preclosing_retag_apply_ready=false")
        if report.get("baselane_85104_preclosing_retag_apply_digest_ok") is not True:
            if report.get("baselane_85104_preclosing_retag_apply_digest_present") is True:
                blockers.append("BASELANE_85104_PRECLOSING_RETAG_APPLY_DIGEST_mismatch")
            else:
                blockers.append("BASELANE_85104_PRECLOSING_RETAG_APPLY_DIGEST_not_provided")
        for blocker in report.get("baselane_85104_preclosing_retag_apply_readiness_blockers") or []:
            if (
                str(blocker) == "BASELANE_85104_PRECLOSING_RETAG_APPLY_DIGEST_mismatch"
                and report.get("baselane_85104_preclosing_retag_apply_digest_present") is not True
            ):
                continue
            if blocker not in blockers:
                blockers.append(str(blocker))
        if partial_ready:
            blockers.append("baselane_85104_preclosing_retag_partial_apply_ready=true")
            blockers.append(
                "baselane_85104_preclosing_retag_partial_apply_will_not_clear_validation_without_protected_rows"
            )
        if protected_blocked_count:
            blockers.append(f"baselane_85104_preclosing_retag_protected_closing_row_count={protected_blocked_count}")
        if protected_blocked_count and protected_review_status != "ok":
            blockers.append(
                f"baselane_85104_preclosing_retag_protected_closing_row_review_status={protected_review_status or 'missing'}"
            )
        if full_blocked_count:
            blockers.append(f"baselane_85104_preclosing_retag_full_blocked_count={full_blocked_count}")
        if int(report.get("baselane_85104_preclosing_retag_payload_transaction_count") or 0) <= 0:
            blockers.append("baselane_85104_preclosing_retag_payload_transaction_count_zero")
        if report.get("baselane_85104_preclosing_retag_status") != "ok":
            blockers.append(f"baselane_85104_preclosing_retag_status={report.get('baselane_85104_preclosing_retag_status')}")
        return {
            "ready_to_run": not blockers,
            "preflight_status": "ready" if not blockers else "blocked",
            "preflight_blockers": blockers,
            "safe_to_run_automatically": False,
            "recommended_command_artifact": "baselane_85104_preclosing_retag_commands",
            "partial_command_artifact": (
                "baselane_85104_preclosing_retag_partial_commands" if partial_ready else None
            ),
            "partial_apply_ready": partial_ready,
            "partial_apply_ack_env": partial_ack_env if partial_ready else None,
            "partial_apply_warning": (
                "Partial apply can remove ready rows but monthly close remains blocked until protected closing rows are reviewed and removed from the property GL; "
                f"the partial command requires {partial_ack_env}=1."
                if partial_ready
                else None
            ),
        }
    if name == "quitman_804_cash_alignment":
        review_count = int(report.get("quitman_804_cash_alignment_review_count") or 0)
        source_clean_status = str(report.get("quitman_804_cash_alignment_source_clean_status") or "review")
        blockers = []
        if review_count > 0:
            blockers.append(f"classification_review_count={review_count}")
        if source_clean_status != "ok":
            blockers.append(f"source_clean_status={source_clean_status}")
        return {
            "ready_to_run": False,
            "preflight_status": "review_required" if blockers else "manual_review",
            "preflight_blockers": blockers,
            "safe_to_run_automatically": False,
        }
    if name in {"transfer_reconciliation_total", "transfer_reconciliation_source_clean_and_final"}:
        blockers = [
            str(item)
            for item in (report.get("transfer_reconciliation_source_blockers") or [])
            if str(item or "")
        ]
        blockers.extend(
            str(item)
            for item in (report.get("transfer_reconciliation_property_cash_review_blockers") or [])
            if str(item or "")
        )
        if report.get("transfer_reconciliation_recommended_total_is_final") is not True:
            blockers.insert(0, "recommended_send_to_lofty_total_is_final=false")
        return {
            "ready_to_run": False,
            "preflight_status": "blocked" if blockers else "manual_review",
            "preflight_blockers": blockers,
            "safe_to_run_automatically": False,
        }
    if name == "discord_property_update":
        blockers: list[str] = []
        if report.get("lofty_pm_publish_report_status") != "ok":
            blockers.append(f"lofty_pm_publish_report_status={report.get('lofty_pm_publish_report_status')}")
        if report.get("lofty_pm_publish_apply") is not True:
            blockers.append("lofty_pm_publish_apply=false")
        if report.get("lofty_pm_publish_publish_attempted") is not True:
            blockers.append("lofty_pm_publish_publish_attempted=false")
        if report.get("lofty_pm_publish_current_for_run") is not True:
            blockers.append("lofty_pm_publish_current_for_run=false")
        if int(report.get("lofty_pm_publish_failed_count") or 0) != 0:
            blockers.append(f"lofty_pm_publish_failed_count={report.get('lofty_pm_publish_failed_count')}")
        if int(report.get("lofty_pm_publish_financial_publish_failed_count") or 0) != 0:
            blockers.append(
                f"lofty_pm_publish_financial_publish_failed_count={report.get('lofty_pm_publish_financial_publish_failed_count')}"
            )
        if report.get("discord_all_send_plan_validation_status") != "ok":
            blockers.append(f"discord_all_send_plan_validation_status={report.get('discord_all_send_plan_validation_status')}")
        for key in (
            "discord_all_send_plan_validation_unmapped_count",
            "discord_all_send_plan_validation_stale_route_count",
            "discord_all_send_plan_validation_missing_financial_summary_count",
            "discord_all_send_plan_validation_non_financial_issue_count",
        ):
            value = report.get(key)
            if value not in (None, 0, "ok"):
                blockers.append(f"{key}={value}")
        if report.get("guild_test_post_valid") is False:
            blockers.append("guild_test_post_valid=false")
        if report.get("discord_all_send_plan_validation_discord_review_ready") is False:
            blockers.append("discord_review_ready=false")
        return {
            "ready_to_run": not blockers,
            "preflight_status": "ready" if not blockers else "blocked",
            "preflight_blockers": blockers,
            "safe_to_run_automatically": False,
            "safe_to_run_automatically_reason": "live Discord messages require an explicit operator decision",
        }
    return {
        "ready_to_run": False,
        "preflight_status": "manual_review",
        "preflight_blockers": [],
        "safe_to_run_automatically": False,
    }


def build_blocker_command_index(report: dict[str, Any]) -> list[dict[str, Any]]:
    artifacts = report.get("artifacts") if isinstance(report.get("artifacts"), dict) else {}
    run_month = str(report.get("run_month") or os.environ.get("RUN_MONTH") or "2026-06").strip() or "2026-06"
    index: list[dict[str, Any]] = []
    order = 0
    default_artifacts = {
        "baselane_raw_daily_sync_fresh_and_effective": [
            "daily_sync_report",
        ],
        "discord_property_update": [
            "discord_all_send_plan",
            "discord_all_send_plan_validation",
            "discord_property_update_send",
            "guild_test_post_report",
        ],
        "lofty_live_listing_financial_update": [
            "lofty_pm_runtime_map",
            "lofty_pm_publish",
            "lofty_live_updates_full_local_restore",
            "lofty_live_updates_history_containment",
            "lofty_financial_patch_readiness",
            "lofty_financial_patch_readiness_blockers",
            "lofty_financial_patch_readiness_blockers_csv",
            "review_manifest",
            "lofty_live_financial_capture",
            "review_candidate_packet",
        ],
        "owner_email_packet_and_send_guard": [
            "lofty_pm_runtime_map",
            "owner_email_packet",
            "owner_email_send_guard",
            "discord_property_update_send",
            "discord_all_send_plan_validation",
            "guild_test_post_report",
            "review_candidate_packet",
        ],
        "owner_email_final_financial_gate": [
            "owner_email_send_guard",
            "transfer_reconciliation",
            "transfer_reconciliation_telegram_send",
            "discord_all_send_plan_validation",
        ],
    }
    default_commands = {
        "baselane_monthly_finance_truth_refresh": (
            f"bash scripts/baselane_financials_post_auth_resume.sh --month {run_month}"
        ),
        "baselane_raw_daily_sync_fresh_and_effective": (
            "bash scripts/baselane_cron_run.sh && python3 scripts/baselane_daily_sync_report.py"
        ),
        "monthly_statements_and_cf_sync": (
            f"RUN_MONTH={run_month} DRY_RUN=1 SEND_OWNER_EMAILS=0 PUBLISH_LOFTY_PM_UPDATES=0 APPLY_LOFTY_GUARDED_UPDATES=0 "
            "bash scripts/baselane_financials_monthly_cron.sh"
        ),
        "accrual_completeness_guard": (
            f"python3 scripts/baselane_monthly_accruals_idempotent.py --month {run_month}"
        ),
        "financials_md_to_lofty_listing_field_readiness": (
            "python3 scripts/lofty_financial_patch_readiness.py "
            "--runtime-map reports/baselane_financials_monthly_lofty_pm_runtime_map.json "
            "--live-financial-capture-report reports/baselane_financials_monthly_live_financial_capture.json "
            "--review-candidate-packet-report reports/baselane_financials_monthly_review_candidate_packet.json "
            "--report reports/lofty_financial_patch_readiness.json"
        ),
        "monthly_active_candidate_set_coverage": (
            "python3 scripts/audit_monthly_pipeline_candidate_coverage.py"
        ),
        "monthly_live_final_send_deadline_gate": (
            f"RUN_MONTH={run_month} DRY_RUN=1 SEND_OWNER_EMAILS=0 PUBLISH_LOFTY_PM_UPDATES=0 APPLY_LOFTY_GUARDED_UPDATES=0 "
            "bash scripts/baselane_financials_monthly_cron.sh"
        ),
        "yhome_operating_cash_apply_verify": (
            f"python3 scripts/yhome_operating_cash_apply_verify.py --month {run_month}"
        ),
        "transfer_reconciliation_total": (
            f"python3 scripts/baselane_lofty_transfer_requirements.py --month {run_month}"
        ),
        "transfer_reconciliation_source_clean_and_final": (
            f"python3 scripts/baselane_lofty_transfer_requirements.py --month {run_month}"
        ),
        "source_cash_reconciliation_actions_clear": (
            f"python3 scripts/baselane_daily_source_cash_balance_audit.py --month {run_month} "
            "--report reports/baselane_daily_source_cash_balance_audit.json"
            " && python3 scripts/baselane_source_cash_reconciliation_actions.py "
            "--source-cash-report reports/baselane_daily_source_cash_balance_audit.json "
            "--weekly-cf-report reports/baselane_weekly_cf_statement_sync_report.json "
            "--candidate-packet reports/baselane_financials_monthly_review_candidate_packet.json "
            "--owner-review-gate reports/baselane_monthly_owner_review_gate.json "
            "--zero-row-decisions config/baselane_zero_row_source_ledger_decisions.json "
            "--report reports/baselane_source_cash_reconciliation_actions.json "
            "--markdown reports/baselane_source_cash_reconciliation_actions.md "
            "--csv reports/baselane_source_cash_reconciliation_actions.csv"
        ),
        "discord_property_update": live_discord_property_update_command(report),
        "discord_all_property_route_and_summary_coverage": (
            "python3 scripts/validate_monthly_discord_all_send_plan.py "
            "--plan reports/baselane_financials_monthly_discord_all_send_plan.json "
            "--report reports/baselane_financials_monthly_discord_all_send_plan_validation.json"
        ),
        "lofty_live_listing_financial_update": live_lofty_publish_completion_command(report),
        "owner_email_packet_and_send_guard": (
            f"python3 scripts/lofty_monthly_owner_email_packet.py --dry-run --run-month {run_month} "
            "--runtime-map reports/baselane_financials_monthly_lofty_pm_runtime_map.json "
            "--review-candidate-packet-report reports/baselane_financials_monthly_review_candidate_packet.json "
            "--discord-send-report reports/baselane_financials_monthly_discord_property_update_send.json "
            "--discord-plan-validation-report reports/baselane_financials_monthly_discord_all_send_plan_validation.json "
            "--guild-test-post-report reports/baselane_financials_monthly_guild_test_post.json "
            "--live-update-capture-report reports/baselane_financials_monthly_live_update_capture.json "
            "--listing-cleanup-queue-report reports/lofty_listing_update_cleanup_queue.json "
            "--report reports/baselane_monthly_owner_email_packet.json"
            " && python3 scripts/baselane_owner_email_send_guard.py --report reports/baselane_monthly_owner_email_send_guard.json"
        ),
        "owner_email_final_financial_gate": (
            "python3 scripts/baselane_owner_email_send_guard.py --report reports/baselane_monthly_owner_email_send_guard.json"
        ),
        "telegram_transfer_reconciliation_delivery": (
            "python3 scripts/send_monthly_transfer_reconciliation_telegram.py --dry-run"
        ),
    }

    def add(name: str, action: str, artifact_keys: list[str], command: str | None = None) -> None:
        nonlocal order
        order += 1
        preflight = blocker_preflight(report, name)
        effective_command = command
        if not effective_command and preflight.get("recommended_command_artifact"):
            command_artifact = str(preflight.get("recommended_command_artifact") or "")
            command_path = str(artifacts.get(command_artifact) or "").strip()
            if command_path:
                effective_command = f"bash {command_path}"
            elif command_artifact == "baselane_85104_preclosing_retag_commands":
                effective_command = "bash reports/baselane_85104_preclosing_property_retag_apply.requires-explicit-approval.sh"
        if not effective_command and preflight.get("partial_command_artifact"):
            command_artifact = str(preflight.get("partial_command_artifact") or "")
            command_path = str(artifacts.get(command_artifact) or "").strip()
            if command_path:
                effective_command = f"bash {command_path}"
        index.append(
            {
                "order": order,
                "name": name,
                "action": action,
                "command": effective_command,
                **preflight,
                "artifacts": {key: artifacts.get(key) for key in artifact_keys if artifacts.get(key)},
            }
        )

    if report.get("coownership_gl_policy_validation_status") == "blocked":
        add(
            "coownership_gl_policy_validation",
            "Review co-ownership blocker evidence, then apply the 85-104 retag only after auth and digest gates pass.",
            [
                "coownership_gl_policy_validation",
                "coownership_gl_policy_validation_blockers_csv",
                "coownership_gl_policy_validation_markdown",
                "baselane_85104_preclosing_retag",
                "baselane_85104_preclosing_retag_payload",
                "baselane_85104_preclosing_retag_commands",
                "baselane_85104_preclosing_retag_partial_preview",
                "baselane_85104_preclosing_retag_partial_commands",
            ],
            "bash reports/baselane_85104_preclosing_property_retag_apply.requires-explicit-approval.sh",
        )
    if int(report.get("quitman_804_cash_alignment_review_count") or 0) > 0:
        add(
            "quitman_804_cash_alignment",
            "Review and classify 804 S Quitman cash-alignment groups before transfer reconciliation.",
            [
                "quitman_804_cash_alignment",
                "quitman_804_cash_alignment_review_markdown",
                "quitman_804_cash_alignment_decision_template",
                "quitman_804_cash_alignment_review_queue_csv",
                "quitman_804_cash_alignment_candidate_decisions",
                "quitman_804_cash_alignment_reviewed_template",
                "quitman_804_cash_alignment_proposed_decisions",
                "quitman_804_cash_alignment_decision_validation",
            ],
            "OPEN reports/baselane_804_quitman_cash_alignment_review.md",
        )
    if (
        report.get("transfer_reconciliation_recommended_total_is_final") is not True
        or report.get("transfer_reconciliation_source_blockers")
        or report.get("transfer_reconciliation_property_cash_review_blockers")
    ):
        add(
            "transfer_reconciliation_source_clean_and_final",
            "Refresh required source artifacts, resolve property cash/accrual blockers, then rerun transfer reconciliation.",
            [
                "transfer_reconciliation",
                "review_candidate_packet",
                "daily_source_cash_balance",
                "source_cash_reconciliation_actions",
                "cf_balance_sheet_consistency",
                "monthly_accruals",
                "monthly_accruals_gap_approval_scaffold",
                "quitman_804_cash_alignment",
                "quitman_804_cash_alignment_review_markdown",
                "quitman_804_cash_alignment_import_commands",
                "quitman_804_cash_alignment_reviewed_template",
                "coownership_gl_policy_validation",
            ],
            "python3 scripts/baselane_lofty_transfer_requirements.py --month 2026-06",
        )
    existing = {entry["name"] for entry in index}
    for item in report.get("monthly_completion_next_actions") or []:
        if not isinstance(item, dict):
            continue
        name = str(item.get("name") or "")
        if not name or name in existing:
            continue
        add(
            name,
            str(item.get("action") or ""),
            default_artifacts.get(name, []),
            default_commands.get(name),
        )
        existing.add(name)
    return index


def build_blocker_command_markdown(report: dict[str, Any]) -> str:
    index = report.get("monthly_blocker_command_index") if isinstance(report.get("monthly_blocker_command_index"), list) else []
    lines = [
        "# Monthly Blocker Command Index",
        "",
        f"Status: `{report.get('status')}`",
        f"Failed step: `{report.get('failed_step')}`",
        "",
    ]
    if not index:
        lines.append("- No blockers currently indexed.")
    for item in index:
        if not isinstance(item, dict):
            continue
        lines.extend(
            [
                f"## {item.get('order')}. {item.get('name')}",
                "",
                f"- Action: {item.get('action')}",
                f"- Ready to run: `{str(item.get('ready_to_run') is True).lower()}`",
                f"- Preflight: `{item.get('preflight_status')}`",
                f"- Safe to run automatically: `{str(item.get('safe_to_run_automatically') is True).lower()}`",
            ]
        )
        blockers = item.get("preflight_blockers") if isinstance(item.get("preflight_blockers"), list) else []
        if blockers:
            lines.append("- Preflight blockers:")
            for blocker in blockers:
                lines.append(f"  - `{blocker}`")
        if item.get("command"):
            lines.append(f"- Command: `{item.get('command')}`")
        artifacts = item.get("artifacts") if isinstance(item.get("artifacts"), dict) else {}
        if artifacts:
            lines.append("- Artifacts:")
            for key, value in artifacts.items():
                lines.append(f"  - `{key}`: `{value}`")
        lines.append("")
    return "\n".join(lines).rstrip() + "\n"

def build_monthly_close_status(report: dict[str, Any]) -> dict[str, Any]:
    blockers = report.get("monthly_blocker_command_index") if isinstance(report.get("monthly_blocker_command_index"), list) else []
    next_actions = report.get("monthly_completion_next_actions") if isinstance(report.get("monthly_completion_next_actions"), list) else []
    top_blockers = [
        {
            "order": item.get("order"),
            "name": item.get("name"),
            "action": item.get("action"),
            "command": item.get("command"),
            "preflight_status": item.get("preflight_status"),
            "preflight_blockers": item.get("preflight_blockers") if isinstance(item.get("preflight_blockers"), list) else [],
            "partial_command_artifact": item.get("partial_command_artifact"),
            "partial_apply_ready": item.get("partial_apply_ready"),
            "partial_apply_ack_env": item.get("partial_apply_ack_env"),
            "partial_apply_warning": item.get("partial_apply_warning"),
            "artifacts": item.get("artifacts") if isinstance(item.get("artifacts"), dict) else {},
        }
        for item in blockers[:5]
        if isinstance(item, dict)
    ]
    chain = report.get("lofty_listing_financial_update_chain") if isinstance(report.get("lofty_listing_financial_update_chain"), dict) else {}
    return {
        "status": report.get("status"),
        "failed_step": report.get("failed_step"),
        "run_month": report.get("run_month"),
        "generated_at": report.get("generated_at"),
        "monthly_completion_gap_count": report.get("monthly_completion_gap_count"),
        "next_action": report.get("next_action"),
        "top_next_actions": next_actions[:5],
        "top_blockers": top_blockers,
        "transfer_reconciliation_status": report.get("transfer_reconciliation_status"),
        "transfer_reconciliation_recommended_total": report.get("transfer_reconciliation_recommended_total"),
        "transfer_reconciliation_recommended_total_is_final": report.get("transfer_reconciliation_recommended_total_is_final"),
        "transfer_reconciliation_source_blockers": report.get("transfer_reconciliation_source_blockers") or [],
        "transfer_reconciliation_property_cash_review_blockers": report.get("transfer_reconciliation_property_cash_review_blockers") or [],
        "transfer_reconciliation_property_cash_review_details": (report.get("transfer_reconciliation_property_cash_review_details") or [])[:3],
        "transfer_reconciliation_bank_action_counts": report.get("transfer_reconciliation_bank_action_counts") or {},
        "cf_balance_sheet_consistency_status": report.get("cf_balance_sheet_consistency_status"),
        "cf_balance_sheet_consistency_issue_count": report.get("cf_balance_sheet_consistency_issue_count"),
        "cf_balance_sheet_consistency_yhome_update_required_count": report.get("cf_balance_sheet_consistency_yhome_update_required_count"),
        "yhome_operating_cash_apply_verify_status": report.get("yhome_operating_cash_apply_verify_status"),
        "yhome_operating_cash_apply_verify_reason": report.get("yhome_operating_cash_apply_verify_reason"),
        "yhome_operating_cash_apply_verify_pre_update_required_count": report.get("yhome_operating_cash_apply_verify_pre_update_required_count"),
        "yhome_operating_cash_apply_verify_post_update_required_count": report.get("yhome_operating_cash_apply_verify_post_update_required_count"),
        "yhome_operating_cash_apply_verify_applied_update_count": report.get("yhome_operating_cash_apply_verify_applied_update_count"),
        "yhome_operating_cash_apply_verify_external_write_attempted": report.get("yhome_operating_cash_apply_verify_external_write_attempted"),
        "yhome_operating_cash_apply_verify_report": report.get("yhome_operating_cash_apply_verify_report"),
