        close_status = close_status_writer.write_monthly_close_status(
            Path(close_status_path),
            Path(close_status_markdown_path) if close_status_markdown_path else Path(str(close_status_path) + ".md"),
            report,
        )
    except Exception as exc:
        close_status = {
            "close_status_write_status": "failed",
            "close_status_write_error": str(exc),
            "close_status_report": close_status_path,
            "close_status_markdown": close_status_markdown_path,
        }
report["monthly_close_status_write_status"] = close_status.get("close_status_write_status")
report["monthly_close_status_write_error"] = close_status.get("close_status_write_error")
report["monthly_close_status_report"] = close_status.get("close_status_report")
report["monthly_close_status_markdown"] = close_status.get("close_status_markdown")
close_report_path = Path(str(close_status.get("close_status_report") or ""))
close_markdown_path = Path(str(close_status.get("close_status_markdown") or ""))
monthly_completion_evidence = [
    item for item in report.get("monthly_completion_evidence", [])
    if not (isinstance(item, dict) and item.get("name") == "monthly_close_status_artifact_written")
]
monthly_completion_evidence.append(
    evidence_item(
        "monthly_close_status_artifact_written",
        close_status.get("close_status_write_status") == "written" and close_report_path.is_file() and close_markdown_path.is_file(),
        {
            "write_status": close_status.get("close_status_write_status"),
            "write_error": close_status.get("close_status_write_error"),
            "report": close_status.get("close_status_report"),
            "markdown": close_status.get("close_status_markdown"),
            "report_exists": close_report_path.is_file(),
            "markdown_exists": close_markdown_path.is_file(),
        },
        "monthly close status artifact was not written",
    )
)
monthly_completion_gaps = [item for item in monthly_completion_evidence if not item["ok"]]
report["monthly_completion_evidence"] = monthly_completion_evidence
report["monthly_completion_gap_count"] = len(monthly_completion_gaps)
report["monthly_completion_gaps"] = monthly_completion_gaps
report["monthly_completion_next_actions"] = [
    {
        "name": item.get("name"),
        "gap": item.get("gap"),
        "action": completion_gap_actions.get(str(item.get("name") or ""), "Resolve this monthly completion gap and rerun the monthly report."),
    }
    for item in monthly_completion_gaps
]
if effective_failed_step == "coownership_gl_policy_validation":
    report["monthly_completion_next_actions"] = [
        item for item in report["monthly_completion_next_actions"]
        if item.get("name") != "coownership_gl_policy_validation"
    ]
    report["monthly_completion_next_actions"].insert(
        0,
        {
            "name": "coownership_gl_policy_validation",
            "gap": "co-ownership GL policy validation is blocking monthly close",
            "action": coownership_gl_policy_completion_action(report),
        },
    )
    report["next_action"] = report["monthly_completion_next_actions"][0]["action"]
if effective_failed_step == "baselane_monthly_finance_truth_refresh":
    finance_refresh_action = str(report.get("monthly_finance_truth_refresh_next_action") or "").strip()
    finance_auth_reason = str(report.get("monthly_finance_truth_refresh_auth_recovery_manual_auth_reason") or "")
    finance_auth_issue = str(report.get("monthly_finance_truth_refresh_auth_recovery_issue_summary") or "").strip()
    if finance_refresh_action:
        report["next_action"] = finance_refresh_action
    elif finance_auth_reason in {
        "recovery_attempted_but_baselane_loading_appcheck",
        "recovery_attempted_but_baselane_blank_shell",
        "recovery_attempted_but_baselane_probe_timeout",
    } and finance_auth_issue:
        report["next_action"] = f"{finance_auth_issue} Then rerun monthly finance-truth refresh before downstream CF/FINANCIALS/Lofty/Discord/email outputs."
    elif report.get("baselane_login_wait_reason") == "baselane_login_recaptcha_required":
        report["next_action"] = "Solve Baselane reCAPTCHA in the visible CDP tab, then rerun monthly finance-truth refresh before downstream CF/FINANCIALS/Lofty/Discord/email outputs."
    elif report.get("monthly_finance_truth_refresh_auth_blocked") is True:
        report["next_action"] = "Solve Baselane reCAPTCHA/appcheck in the visible CDP tab, then rerun monthly finance-truth refresh before downstream CF/FINANCIALS/Lofty/Discord/email outputs."
    else:
        report["next_action"] = "Review the Baselane monthly finance-truth refresh error artifact, fix the failed step, then rerun monthly close."
report["monthly_blocker_command_index"] = build_blocker_command_index(report)
if blocker_markdown_path:
    blocker_path.write_text(build_blocker_command_markdown(report), encoding="utf-8")
report["review_step_names"] = sorted(blocking_step_statuses)
report["blocking_step_statuses"] = blocking_step_statuses
report["actionable_review_step_names"] = sorted(actionable_blocking_step_statuses)
report["actionable_blocking_step_statuses"] = actionable_blocking_step_statuses
if report.get("disk_space_preflight_status") == "review":
    report["next_action"] = monthly_disk_next_action(report.get("disk_space_preflight_report") or "")
    report["hold"] = "Lofty PM publish and investor email"
tmp = report_file.with_suffix(report_file.suffix + ".tmp")
tmp.write_text(json.dumps(report, indent=2, sort_keys=True) + "\n", encoding="utf-8")
tmp.replace(report_file)
with history_file.open("a", encoding="utf-8") as handle:
    handle.write(json.dumps(report, sort_keys=True) + "\n")
PY
}

run_owner_review_gate() {
  CURRENT_STEP="monthly_owner_review_gate"
  if [ "$#" -gt 0 ] && [ -n "${1:-}" ]; then
    CURRENT_STEP="$1"
  fi
  OWNER_REVIEW_GATE_SCRIPT="$ROOT/scripts/baselane_monthly_owner_review_gate.py"
  if [ -f "$OWNER_REVIEW_GATE_SCRIPT" ]; then
    set +e
    $PY "$OWNER_REVIEW_GATE_SCRIPT" --root "$ROOT" --report "$OWNER_REVIEW_GATE_FILE" --markdown "$OWNER_REVIEW_GATE_MARKDOWN_FILE" >/dev/null
    owner_review_gate_rc="$?"
    set -e
    if [ "$owner_review_gate_rc" -eq 0 ]; then
      OWNER_REVIEW_GATE_STATUS="ok"
    elif [ "$owner_review_gate_rc" -eq 2 ]; then
      OWNER_REVIEW_GATE_STATUS="review"
    else
      OWNER_REVIEW_GATE_STATUS="failed"
      exit "$owner_review_gate_rc"
    fi
  else
    OWNER_REVIEW_GATE_STATUS="skipped_missing_script"
  fi
}

