import json
import os
from datetime import datetime, timezone
from pathlib import Path

def read_json(path: Path) -> dict:
    if not path.is_file():
        return {}
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return {}
    return data if isinstance(data, dict) else {}

path = Path(os.environ["SAFE_CANDIDATE_APPROVAL_FILE"])
candidate_packet_path = Path(os.environ["REVIEW_CANDIDATE_PACKET_FILE"])
safety_scan_path = Path(os.environ["REVIEW_SAFETY_SCAN_FILE"])
