    "update_candidate_count": candidate_packet.get("update_candidate_count"),
    "financial_candidate_count": candidate_packet.get("financial_candidate_count"),
    "candidate_issue_count": candidate_packet.get("issue_count"),
    "candidate_marker_count": candidate_packet.get("marker_count"),
    "safety_scan": str(safety_scan_path),
    "safety_scan_status": safety_scan.get("status"),
    "safety_high_count": safety_scan.get("high_count"),
    "safety_medium_count": safety_scan.get("medium_count"),
    "safety_missing_count": safety_scan.get("missing_count"),
    "issue_count": 0,
    "property_count": 0,
    "approved_update_count": 0,
    "approved_financial_count": 0,
    "records": [],
}
path.parent.mkdir(parents=True, exist_ok=True)
path.write_text(json.dumps(report, indent=2, sort_keys=True) + "\n", encoding="utf-8")
PY
}

write_lofty_pm_publish_disk_hold_report() {
  LOFTY_PM_PUBLISH_FILE="$LOFTY_PM_PUBLISH_FILE" \
  DISK_PREFLIGHT_REPORT_FILE="$DISK_PREFLIGHT_REPORT_FILE" \
  READINESS_FILE="$READINESS_FILE" \
  RUN_MONTH="$RUN_MONTH" \
  OWNER_EMAIL_INTERVAL_DAYS="$OWNER_EMAIL_INTERVAL_DAYS" \
  EMAIL_SENT_STATE_FILE="$EMAIL_SENT_STATE_FILE" \
  OWNER_EMAIL_SEND_BLOCKED_REASON="$OWNER_EMAIL_SEND_BLOCKED_REASON" \
  $PY - <<'PY'
import json
import os
import sys
from datetime import datetime, timezone
from pathlib import Path
sys.path.insert(0, str(Path.cwd() / "scripts"))
from lofty_monthly_exclusions import DEFAULT_MANUAL_EXCLUDED_PROPERTIES

report_path = Path(os.environ["LOFTY_PM_PUBLISH_FILE"])
disk_report = os.environ["DISK_PREFLIGHT_REPORT_FILE"]
readiness_path = Path(os.environ["READINESS_FILE"])
manual_excluded_property_names = list(DEFAULT_MANUAL_EXCLUDED_PROPERTIES)
def read_disk_report():
    try:
        data = json.loads(Path(disk_report).read_text(encoding="utf-8"))
    except Exception:
        return {}
    return data if isinstance(data, dict) else {}

disk_report_payload = read_disk_report()
blocked_reason = os.environ.get("OWNER_EMAIL_SEND_BLOCKED_REASON") or (
    "monthly disk preflight is review; free local Dropbox/Windows disk before monthly publish/email"
)
disk_action = str(disk_report_payload.get("next_action") or "").strip()
next_action = (
    f"{disk_action} Then rerun scripts/baselane_cron_run.sh and monthly publish/email."
    if disk_action
    else "Free local Dropbox/Windows disk space, rerun scripts/baselane_cron_run.sh, then rerun monthly publish/email."
)
try:
    readiness = json.loads(readiness_path.read_text(encoding="utf-8"))
except Exception:
    readiness = {}
skip_policy = readiness.get("monthly_skip_policy") if isinstance(readiness.get("monthly_skip_policy"), dict) else {}
excluded_property_count = int(skip_policy.get("lofty_pm_publish_excluded_property_count") or 0)
excluded_payload_file_count = int(skip_policy.get("lofty_pm_publish_excluded_payload_file_count") or 0)
try:
    send_interval_days = int(os.environ.get("OWNER_EMAIL_INTERVAL_DAYS") or 7)
except ValueError:
    send_interval_days = 7
readiness_snapshot = {
    "path": str(readiness_path),
    "status": readiness.get("status"),
    "run_month": readiness.get("run_month"),
    "owner_email_allowed": readiness.get("owner_email_allowed"),
    "owner_email_blocked_reason": readiness.get("owner_email_blocked_reason"),
    "blocker_count": readiness.get("blocker_count"),
    "blocked_property_count": readiness.get("blocked_property_count"),
    "primary_blocker": readiness.get("primary_blocker")
    if isinstance(readiness.get("primary_blocker"), dict)
    else (readiness.get("actionable_summary") or {}).get("primary_blocker", {}),
    "counts": readiness.get("counts") or {},
    "actionable_summary": readiness.get("actionable_summary")
    if isinstance(readiness.get("actionable_summary"), dict)
    else {},
}
readiness_snapshot["digest"] = __import__("hashlib").sha256(
    json.dumps(readiness_snapshot, sort_keys=True, separators=(",", ":"), default=str).encode("utf-8")
).hexdigest()
readiness_snapshot["source_generated_at"] = readiness.get("generated_at")
send_decision_inputs = {
    "run_month": os.environ["RUN_MONTH"],
    "requested": False,
    "send_interval_days": send_interval_days,
    "readiness_digest": readiness_snapshot["digest"],
    "readiness_owner_email_allowed": False,
    "guild_test_post_required": True,
    "guild_test_post_valid": False,
    "native_owner_email_allowed": False,
    "guarded_apply_status": "blocked_disk_space_preflight",
    "guarded_apply_apply": False,
    "property_count": 0,
    "will_send_count": 0,
    "send_evidence_count": 0,
}
send_decision_digest = __import__("hashlib").sha256(
    json.dumps(send_decision_inputs, sort_keys=True, separators=(",", ":"), default=str).encode("utf-8")
).hexdigest()
primary_blocker = {
    "artifact": disk_report,
    "blocker": "operational.disk_space_preflight.not_ok",
    "class": "operational.disk_space_preflight.not_ok",
    "evidence": disk_report,
    "hold": "Lofty PM publish and investor email",
    "next_action": next_action,
    "source": "baselane_disk_space_preflight",
    "summary": "Low local disk space blocks monthly Lofty PM publish and owner email.",
}
report = {
    "generated_at": datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z"),
    "run_month": os.environ["RUN_MONTH"],
    "status": "review",
    "reason": "disk-space-preflight",
    "issue_count": 1,
    "safe_external_effect": False,
    "send_blocked": True,
    "next_action": next_action,
    "disk_space_preflight_next_action": disk_action or None,
    "disk_space_preflight_required_free_mib": disk_report_payload.get("required_free_mib"),
    "hold": "Lofty PM publish and investor email",
    "active_property_only_policy": (
        "Yhome sold/delisted guard, manual property exclusions, and owner-email exclusions "
        "must prevent live updates and owner emails for inactive properties."
    ),
    "description_check_blocking_count": 0,
    "description_check_policy": "DESCRIPTION.md uses rent-roll and Lofty-live staleness checks before owner email.",
    "description_check_report": {
        "reason": "upstream disk hold; no DESCRIPTION.md publish attempted",
        "status": "ok",
    },
    "description_check_status": "ok",
    "effective_send_owner_emails": False,
    "excluded_owner_email_candidate_count": 0,
    "excluded_payload_file_count": excluded_payload_file_count,
    "excluded_property_count": excluded_property_count,
    "listing_update_full_history_count": 0,
    "listing_update_guard_issue_count": 0,
    "listing_update_non_history_count": 0,
    "listing_update_policy": (
        "Lofty listing updates must preserve full UPDATES.md history; owner emails must contain only "
        "the current signal update."
    ),
    "manual_excluded_property_names": manual_excluded_property_names,
    "owner_email_idempotency": {
        "configured": True,
        "max_send_per_month": True,
        "safe_to_send_now": False,
        "send_blocked_reason": blocked_reason,
        "send_decision_digest": send_decision_digest,
        "sent_state_file": os.environ["EMAIL_SENT_STATE_FILE"],
    },
    "primary_blocker": primary_blocker,
    "records": [],
    "send_decision_digest": send_decision_digest,
    "send_decision_inputs": send_decision_inputs,
    "send_interval_days": send_interval_days,
    "sent_state_file": os.environ["EMAIL_SENT_STATE_FILE"],
    "send_lock_status": "not_requested",
    "sent_state_write_status": "not_requested",
    "monthly_readiness_snapshot": readiness_snapshot,
    "send_owner_emails": False,
    "guild_test_post_required_before_email": True,
    "guild_test_post_snapshot": {
        "status": "not_posted_blocked_by_disk_preflight",
        "valid": False,
        "posted": False,
        "run_month": os.environ["RUN_MONTH"],
        "target": None,
        "guild_id": None,
        "selected": None,
        "publication_state": "held_not_posted",
        "human_approval_required": True,
        "next_action": "Resolve disk preflight before preparing or posting a guild test update.",
    },
    "yhome_transition_guard": {
        "status": "ok",
        "excluded_count": excluded_property_count,
        "column_b_header": "New PM",
        "column_b_rule": "Yhome Transition Reconciliation column B sold/selling rows are excluded.",
        "column_b_marker_count": excluded_property_count,
        "column_b_rule_ok": True,
    },
    "actionable_summary": {
        "actionable_blocker_count": 1,
        "primary_blocker": primary_blocker,
        "safe_external_effect": False,
        "send_blocked": True,
    },
    "owner_email_send_decision": {
        "blocked_reason": blocked_reason,
        "effective": False,
        "requested": False,
        "safe_to_send_now": False,
        "send_decision_digest": send_decision_digest,
        "will_send_count": 0,
    },
    "publish_results": [],
    "financial_publish_results": [],
}
report_path.parent.mkdir(parents=True, exist_ok=True)
report_path.write_text(json.dumps(report, indent=2, sort_keys=True) + "\n", encoding="utf-8")
PY
}

write_lofty_pm_publish_upstream_hold_report() {
