PY
}

write_lofty_pm_publish_upstream_failure_hold_report() {
  LOFTY_PM_PUBLISH_FILE="$LOFTY_PM_PUBLISH_FILE" \
  MONTHLY_RUN_REPORT_FILE="$REPORT_FILE" \
  MONTHLY_FINANCE_TRUTH_REFRESH_FILE="$MONTHLY_FINANCE_TRUTH_REFRESH_FILE" \
  CURRENT_STEP="$CURRENT_STEP" \
  RUN_MONTH="$RUN_MONTH" \
  $PY - <<'PY'
import json
import os
from datetime import datetime, timezone
from pathlib import Path


def read_json(path):
    try:
        value = json.loads(Path(path).read_text(encoding="utf-8"))
    except Exception:
        return {}
    return value if isinstance(value, dict) else {}


publish_path = Path(os.environ["LOFTY_PM_PUBLISH_FILE"])
existing = read_json(publish_path)
current_step = os.environ.get("CURRENT_STEP") or "monthly_upstream"
truth_path = Path(os.environ["MONTHLY_FINANCE_TRUTH_REFRESH_FILE"])
truth = read_json(truth_path)

# Preserve the more specific auth hold written immediately before the trap.
if (
    existing.get("status") == "blocked_upstream"
    and existing.get("reason") == "baselane-auth-preflight"
    and current_step == "baselane_monthly_finance_truth_refresh"
):
    raise SystemExit(0)

run_report_path = Path(os.environ["MONTHLY_RUN_REPORT_FILE"])
run_report = read_json(run_report_path)
failed_step = str(run_report.get("failed_step") or current_step).strip()
auth_blocked = truth.get("auth_blocked") is True and truth.get("downstream_generation_allowed") is False
if auth_blocked:
    reason = "baselane-auth-preflight"
    blocker = "operational.baselane_auth_preflight.not_ok"
    summary = "Baselane authentication did not pass, so no downstream financial write was attempted."
else:
    reason = f"upstream-{failed_step}"
    blocker = f"operational.{failed_step}.not_ok"
    summary = "Monthly close stopped before downstream financial publish; no Lofty write was attempted."
next_action = str(
    truth.get("next_action")
    or run_report.get("next_action")
    or "Resolve the upstream monthly-close blocker, then rerun the guarded monthly pipeline."
).strip()
primary_blocker = {
    "artifact": str(truth_path if auth_blocked else run_report_path),
    "blocker": blocker,
    "class": blocker,
    "evidence": {
        "monthly_run_status": run_report.get("status"),
        "monthly_run_effective_status": run_report.get("effective_status"),
        "failed_step": failed_step,
        "finance_truth_status": truth.get("status"),
        "auth_blocked": truth.get("auth_blocked"),
        "downstream_generation_allowed": truth.get("downstream_generation_allowed"),
    },
    "hold": "Lofty PM financial publish, Discord post, and investor email",
    "next_action": next_action,
    "source": "baselane_monthly_upstream_gate",
    "summary": summary,
}
report = {
    "generated_at": datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z"),
    "run_month": os.environ["RUN_MONTH"],
    "status": "blocked_upstream",
    "reason": reason,
    "issue_count": 1,
    "safe_external_effect": False,
    "publish_attempted": False,
    "lofty_pm_publish_publish_attempted": False,
    "publish_result_count": 0,
    "publish_failed_count": 0,
    "financial_publish_result_count": 0,
    "financial_publish_failed_count": 0,
    "lofty_pm_publish_guarded_apply_status": "blocked_upstream",
    "guarded_apply_status": "blocked_upstream",
    "guarded_apply_apply": False,
    "guarded_apply_live_ready": False,
    "send_blocked": True,
    "next_action": next_action,
    "hold": "Lofty PM financial publish, Discord post, and investor email",
    "effective_send_owner_emails": False,
    "primary_blocker": primary_blocker,
    "upstream_monthly_run_report": str(run_report_path),
    "upstream_finance_truth_report": str(truth_path),
    "records": [],
    "publish_results": [],
    "financial_publish_results": [],
}
publish_path.parent.mkdir(parents=True, exist_ok=True)
publish_path.write_text(json.dumps(report, indent=2, sort_keys=True) + "\n", encoding="utf-8")
PY
}

write_lofty_pm_publish_disabled_report() {
  LOFTY_PM_PUBLISH_FILE="$LOFTY_PM_PUBLISH_FILE" \
  READINESS_FILE="$READINESS_FILE" \
  MONTHLY_INDEX_CSV="$MONTHLY_INDEX_CSV" \
  LIVE_UPDATE_CAPTURE_FILE="$LIVE_UPDATE_CAPTURE_FILE" \
  LIVE_FINANCIAL_CAPTURE_FILE="$LIVE_FINANCIAL_CAPTURE_FILE" \
  RUN_MONTH="$RUN_MONTH" \
  OWNER_EMAIL_INTERVAL_DAYS="$OWNER_EMAIL_INTERVAL_DAYS" \
  EMAIL_SENT_STATE_FILE="$EMAIL_SENT_STATE_FILE" \
  OWNER_EMAIL_SEND_BLOCKED_REASON="$OWNER_EMAIL_SEND_BLOCKED_REASON" \
  $PY - <<'PY'
import csv
import hashlib
import json
import os
import sys
from datetime import datetime, timezone
from pathlib import Path
sys.path.insert(0, str(Path.cwd() / "scripts"))
from lofty_monthly_exclusions import DEFAULT_MANUAL_EXCLUDED_PROPERTIES

report_path = Path(os.environ["LOFTY_PM_PUBLISH_FILE"])
index_path = Path(os.environ["MONTHLY_INDEX_CSV"])
readiness_path = Path(os.environ["READINESS_FILE"])
manual_excluded_property_names = list(DEFAULT_MANUAL_EXCLUDED_PROPERTIES)

def read_json(path: Path) -> dict:
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return {}
    return data if isinstance(data, dict) else {}

readiness = read_json(readiness_path)
live_update_capture = read_json(Path(os.environ["LIVE_UPDATE_CAPTURE_FILE"]))
live_financial_capture = read_json(Path(os.environ["LIVE_FINANCIAL_CAPTURE_FILE"]))
property_count = 0
if index_path.exists():
    try:
        with index_path.open(newline="", encoding="utf-8-sig") as handle:
            property_count = sum(1 for _ in csv.DictReader(handle))
    except Exception:
        property_count = 0
try:
    send_interval_days = int(os.environ.get("OWNER_EMAIL_INTERVAL_DAYS") or 7)
except ValueError:
    send_interval_days = 7
live_excluded_count = int(
    live_update_capture.get("excluded_property_count")
    or live_financial_capture.get("excluded_property_count")
    or 0
)
live_skipped_count = int(
    live_update_capture.get("skipped_index_count")
    or live_financial_capture.get("skipped_index_count")
    or 0
)
live_external_count = int(
    live_update_capture.get("externally_excluded_count")
    or live_financial_capture.get("externally_excluded_count")
    or max(0, live_excluded_count - live_skipped_count)
)
excluded_property_names = [
    str(name)
    for name in (
        live_update_capture.get("excluded_property_names")
        or live_financial_capture.get("excluded_property_names")
        or []
    )
    if str(name or "").strip()
]
readiness_snapshot = {
    "path": str(readiness_path),
    "status": readiness.get("status"),
    "run_month": readiness.get("run_month"),
    "owner_email_allowed": readiness.get("owner_email_allowed"),
    "owner_email_blocked_reason": readiness.get("owner_email_blocked_reason"),
    "blocker_count": readiness.get("blocker_count"),
    "blocked_property_count": readiness.get("blocked_property_count"),
    "primary_blocker": readiness.get("primary_blocker")
    if isinstance(readiness.get("primary_blocker"), dict)
    else (readiness.get("actionable_summary") or {}).get("primary_blocker", {}),
    "counts": readiness.get("counts") or {},
    "actionable_summary": readiness.get("actionable_summary")
    if isinstance(readiness.get("actionable_summary"), dict)
    else {},
}
readiness_snapshot["digest"] = hashlib.sha256(
    json.dumps(readiness_snapshot, sort_keys=True, separators=(",", ":"), default=str).encode("utf-8")
).hexdigest()
readiness_snapshot["source_generated_at"] = readiness.get("generated_at")
blocked_reason = os.environ.get("OWNER_EMAIL_SEND_BLOCKED_REASON") or "PUBLISH_LOFTY_PM_UPDATES disabled"
send_decision_inputs = {
    "run_month": os.environ["RUN_MONTH"],
    "requested": False,
    "effective": False,
    "send_interval_days": send_interval_days,
    "readiness_digest": readiness_snapshot["digest"],
    "readiness_owner_email_allowed": readiness.get("owner_email_allowed") is True,
    "native_owner_email_allowed": False,
    "publish_attempted": False,
    "property_count": property_count,
    "will_send_count": 0,
    "send_evidence_count": 0,
}
send_decision_digest = hashlib.sha256(
    json.dumps(send_decision_inputs, sort_keys=True, separators=(",", ":"), default=str).encode("utf-8")
).hexdigest()
report = {
    "generated_at": datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z"),
    "run_month": os.environ["RUN_MONTH"],
    "status": "ok_not_published",
    "reason": "PUBLISH_LOFTY_PM_UPDATES disabled",
    "issue_count": 0,
    "property_count": property_count,
    "publish_attempted": False,
    "publish_result_count": 0,
    "publish_failed_count": 0,
    "financial_publish_failed_count": 0,
    "safe_external_effect": False,
    "send_blocked": True,
    "owner_email_blocked_reason": blocked_reason,
    "active_property_only_policy": (
        "Yhome sold/delisted rows, manual exclusions, and owner-email exclusions are excluded "
        "from Lofty PM publish payloads and owner-email send candidates."
    ),
    "description_check_blocking_count": 0,
    "description_check_policy": (
        "Monthly publish requires active-property DESCRIPTION.md to be reconciled against the current "
        "rent-roll occupancy summary, or a Lofty-live occupancy/rent/lease fallback when no rent-roll "
        "match exists, before live listing update or owner email."
    ),
    "description_check_report": {
        "reason": "publish disabled; no DESCRIPTION.md live update attempted",
        "status": "ok",
        "blocking_count": 0,
        "source_issue_count": 0,
        "records": [],
    },
    "description_check_status": "ok",
    "effective_send_owner_emails": False,
    "excluded_owner_email_candidate_count": 0,
    "excluded_payload_file_count": 0,
    "excluded_property_count": live_excluded_count,
    "excluded_property_names": excluded_property_names,
    "skipped_index_count": live_skipped_count,
    "externally_excluded_count": live_external_count,
    "live_update_excluded_property_count": live_update_capture.get("excluded_property_count"),
    "live_financial_excluded_property_count": live_financial_capture.get("excluded_property_count"),
    "listing_update_full_history_count": 0,
    "listing_update_guard_issue_count": 0,
    "listing_update_non_history_count": 0,
    "listing_update_policy": (
        "Lofty listing updates must preserve full UPDATES.md history; owner emails must contain only "
        "the current signal update."
    ),
    "manual_excluded_property_names": manual_excluded_property_names,
    "monthly_readiness_snapshot": readiness_snapshot,
    "owner_email_idempotency": {
        "configured": True,
        "max_send_per_month": True,
        "run_month": os.environ["RUN_MONTH"],
        "safe_to_send_now": False,
        "send_blocked_reason": blocked_reason,
        "send_decision_digest": send_decision_digest,
        "sent_state_file": os.environ["EMAIL_SENT_STATE_FILE"],
    },
    "owner_email_send_decision": {
        "requested": False,
        "effective": False,
        "send_decision_digest": send_decision_digest,
    },
    "send_decision_digest": send_decision_digest,
    "send_decision_inputs": send_decision_inputs,
    "send_interval_days": send_interval_days,
    "sent_state_file": os.environ["EMAIL_SENT_STATE_FILE"],
    "send_lock_status": "not_requested",
    "sent_state_write_status": "not_requested",
    "send_owner_emails": False,
    "guild_test_post_required_before_email": True,
    "guild_test_post_snapshot": {
        "status": "not_posted_publish_disabled",
        "valid": False,
        "prepared": False,
        "posted": False,
        "run_month": os.environ["RUN_MONTH"],
    },
    "records": [],
    "publish_results": [],
    "financial_publish_results": [],
    "issues": [],
}
report_path.parent.mkdir(parents=True, exist_ok=True)
report_path.write_text(json.dumps(report, indent=2, sort_keys=True) + "\n", encoding="utf-8")
PY
}

write_owner_email_packet_disk_hold_report() {
  OWNER_EMAIL_PACKET_FILE="$OWNER_EMAIL_PACKET_FILE" \
  LOFTY_PM_RUNTIME_MAP="$LOFTY_PM_RUNTIME_MAP" \
  OWNER_EMAIL_RECIPIENTS_CSV="$OWNER_EMAIL_RECIPIENTS_CSV" \
  OWNER_EMAIL_PACKET_SENT_STATE_FILE="$OWNER_EMAIL_PACKET_SENT_STATE_FILE" \
  OWNER_EMAIL_PACKET_PREVIEW_DIR="$OWNER_EMAIL_PACKET_PREVIEW_DIR" \
  DISK_PREFLIGHT_REPORT_FILE="$DISK_PREFLIGHT_REPORT_FILE" \
  LIVE_UPDATE_CAPTURE_FILE="$LIVE_UPDATE_CAPTURE_FILE" \
  LOFTY_LISTING_CLEANUP_QUEUE_FILE="$LOFTY_LISTING_CLEANUP_QUEUE_FILE" \
  OWNER_EMAIL_PACKET_REVIEW_CANDIDATE_FILE="$OWNER_EMAIL_PACKET_REVIEW_CANDIDATE_FILE" \
  RUN_MONTH="$RUN_MONTH" \
  $PY - <<'PY'
import hashlib
import json
import os
from datetime import datetime, timezone
from pathlib import Path

report_path = Path(os.environ["OWNER_EMAIL_PACKET_FILE"])
