disk_report = os.environ["DISK_PREFLIGHT_REPORT_FILE"]
live_update_capture = os.environ["LIVE_UPDATE_CAPTURE_FILE"]
listing_cleanup_queue = os.environ["LOFTY_LISTING_CLEANUP_QUEUE_FILE"]
review_candidate_packet = os.environ["OWNER_EMAIL_PACKET_REVIEW_CANDIDATE_FILE"]
run_month = os.environ["RUN_MONTH"]
try:
    disk_report_payload = json.loads(Path(disk_report).read_text(encoding="utf-8"))
except Exception:
    disk_report_payload = {}
if not isinstance(disk_report_payload, dict):
    disk_report_payload = {}
disk_action = str(disk_report_payload.get("next_action") or "").strip()
next_action = (
    f"{disk_action} Then rerun scripts/baselane_cron_run.sh and monthly publish/email."
    if disk_action
    else "Free local Dropbox/Windows disk space, rerun scripts/baselane_cron_run.sh, then rerun monthly publish/email."
)
primary_blocker = {
    "id": "operational.disk_space_preflight.not_ok",
    "class": "operational.disk_space_preflight.not_ok",
    "summary": "Low local disk space blocks monthly owner-email packet generation.",
    "blocker": "operational.disk_space_preflight.not_ok",
    "artifact": disk_report,
    "next_action": next_action,
    "hold": "Lofty PM publish and investor email",
}
actionable_summary = {
    "actionable_blocker_count": 1,
    "noise_policy": "Use primary_blocker for action; packet generation is intentionally held before any email preview or send.",
    "primary_blocker": primary_blocker,
    "property_unavailable_reason_counts": {},
    "secondary_blockers": [],
}
digest_payload = {
    "run_month": run_month,
    "primary_blocker": primary_blocker,
    "packet_count": 0,
    "safe_to_send_now": False,
    "disk_space_preflight_next_action": disk_action or None,
    "disk_space_preflight_required_free_mib": disk_report_payload.get("required_free_mib"),
}
stale_preview_file_removed_count = 0
stale_preview_cleanup_errors = []
if preview_dir.exists():
    for path in sorted(preview_dir.glob("*.txt")):
        try:
            if path.is_file() or path.is_symlink():
                path.unlink()
                stale_preview_file_removed_count += 1
        except OSError as exc:
            stale_preview_cleanup_errors.append(f"stale preview cleanup failed for {path}: {exc}")
report = {
    "generated_at": datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z"),
    "status": "review",
    "classification": "lofty-monthly-owner-email-packet-review",
    "issue_count": 1,
    "issues": ["monthly disk preflight is review; owner-email packet generation is held"],
    "issue_classes": ["lofty-monthly-owner-email-packet-review"],
    "actionable_summary": actionable_summary,
    "primary_blocker": primary_blocker,
    "next_action": next_action,
    "hold": "Lofty PM publish and investor email",
    "run_month": run_month,
    "runtime_map": str(runtime_map),
    "runtime_map_exists": runtime_map.is_file(),
    "runtime_map_canonical_name_ok": runtime_map.name == "baselane_financials_monthly_lofty_pm_runtime_map.json",
    "runtime_map_expected_name": "baselane_financials_monthly_lofty_pm_runtime_map.json",
    "live_update_capture_report": live_update_capture,
    "listing_cleanup_queue_report": listing_cleanup_queue,
    "review_candidate_packet_report": review_candidate_packet,
    "guild_test_post_report": None,
    "require_guild_test_post_before_email": True,
    "guild_test_post_required": False,
    "guild_test_post_ok": False,
    "guild_test_post_valid": False,
    "guild_test_post_posted": False,
    "guild_test_post_status": "not_prepared_disk_space_preflight",
    "guild_test_post_issues": [],
    "requires_live_update_guard": True,
    "recipients_csv": str(recipients_csv),
    "recipient_template_csv": str(recipients_csv.with_name(f"{recipients_csv.stem}.template{recipients_csv.suffix}")),
    "recipient_template_written": False,
    "recipient_csv_required_fields": [],
    "recipient_csv_policy": "No recipient CSV is required for native Lofty PM MCP sends; non-native packet path remains held.",
    "owner_email_send_policy": "Signal-only owner emails; never include full UPDATES.md history.",
    "native_lofty_owner_email_allowed": False,
    "native_lofty_owner_email_recipient_source": "lofty_pm_mcp",
    "native_lofty_owner_email_content_source": "per-property latest approved update plus verified financial summary",
    "native_lofty_owner_email_preview_count": 0,
    "native_lofty_owner_email_preview_file_write_allowed": False,
    "native_lofty_owner_email_body_guard_issue_count": 0,
    "native_lofty_owner_email_previews": [],
    "non_native_signal_only_owner_email_allowed": False,
    "non_native_recipient_csv_required": False,
    "non_native_recipient_csv_exists": recipients_csv.is_file(),
    "non_native_recipient_issue_count": 0,
    "non_native_recipient_issues": [],
    "sent_state_file": str(sent_state_file),
    "sent_state_status": "not_checked_disk_space_preflight",
    "sent_state_month": "",
    "already_sent_for_run_month": False,
    "max_once_monthly_ok": True,
    "property_email_cooldown_days": 7,
    "property_email_cooldown_ok": True,
    "property_email_cooldown_issue_count": 0,
    "property_email_cooldown_issues": [],
    "subject": f"Lofty monthly update - {run_month}",
    "dry_run": True,
    "send_requested": False,
    "send_env": "LOFTY_MONTHLY_OWNER_EMAIL_SEND_APPROVED",
    "send_env_enabled": False,
    "gws_available": False,
    "gws_binary": None,
    "property_count": 0,
    "available_property_count": 0,
    "property_unavailable_count": 0,
    "property_unavailable_bounded": [],
    "property_unavailable_reason_counts": {},
    "property_gap_csv": str(report_path.with_name("baselane_monthly_owner_email_property_gaps.csv")),
    "property_gap_csv_written": False,
    "property_gap_csv_fields": [],
    "recipient_count": 0,
    "packet_count": 0,
    "full_history_leak_count": 0,
    "full_history_guard_issue_count": 0,
    "body_guard_issue_count": 0,
    "native_property_load_issue_count": 0,
    "native_property_load_issues": [],
    "email_body_max_chars": 3500,
    "email_body_max_lines": 80,
    "property_update_max_chars": 1800,
    "property_update_max_lines": 45,
    "financial_summary_enriched_property_count": 0,
    "monthly_financial_summary_present_property_count": 0,
    "property_unavailable_financial_summary_enriched_count": 0,
    "property_unavailable_monthly_financial_summary_present_count": 0,
    "monthly_financial_summary_present_total_property_count": 0,
    "monthly_financial_summary_missing_property_count": 0,
    "property_unavailable_candidate_update_source_count": 0,
    "property_unavailable_candidate_update_approval_target_count": 0,
    "property_unavailable_candidate_financial_approval_target_count": 0,
    "packet_digest": hashlib.sha256(json.dumps(digest_payload, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest(),
    "safe_to_send_now": False,
    "preview_dir": str(preview_dir),
    "preview_file_write_allowed": False,
    "preview_write_blocked_reason": "no recipient email packets generated; monthly disk preflight is review",
    "unsafe_preview_packet_count": 0,
    "stale_preview_file_removed_count": stale_preview_file_removed_count,
    "stale_preview_cleanup_error_count": len(stale_preview_cleanup_errors),
    "stale_preview_cleanup_errors": stale_preview_cleanup_errors[:10],
    "previews": [],
    "packets_bounded": [],
    "send_result_count": 0,
    "send_failed_count": 0,
    "send_results_bounded": [],
    "sent_state_written": False,
}
report_path.parent.mkdir(parents=True, exist_ok=True)
report_path.write_text(json.dumps(report, indent=2, sort_keys=True) + "\n", encoding="utf-8")
PY
}

handle_monthly_signal() {
  MONTHLY_INTERRUPT_SIGNAL="$1"
  exit 124
}

finish_monthly_report() {
  local rc="$?"
  if [ -n "$MONTHLY_INTERRUPT_SIGNAL" ]; then
    write_monthly_report 124 "review" "$CURRENT_STEP"
  elif [ "$rc" -eq 0 ]; then
    write_monthly_report "$rc" "ok" ""
  else
    write_monthly_report "$rc" "failed" "$CURRENT_STEP"
  fi
  if [ "$rc" -ne 0 ] && [ "$CURRENT_STEP" != "baselane_disk_space_preflight" ]; then
    write_lofty_pm_publish_upstream_failure_hold_report
  elif [ "$CURRENT_STEP" != "baselane_disk_space_preflight" ] && "$PY" - "$MONTHLY_FINANCE_TRUTH_REFRESH_FILE" <<'PY'
import json
import sys
from pathlib import Path

try:
    report = json.loads(Path(sys.argv[1]).read_text(encoding="utf-8"))
except Exception:
    report = {}

blocked = (
    report.get("status") == "failed"
    or report.get("auth_blocked") is True
    or report.get("downstream_generation_allowed") is False
)
raise SystemExit(0 if blocked else 1)
PY
  then
    write_lofty_pm_publish_upstream_failure_hold_report
  fi
  exit "$rc"
}
trap finish_monthly_report EXIT
trap 'handle_monthly_signal TERM' TERM
trap 'handle_monthly_signal INT' INT

mkdir -p "$REPORT_DIR" "$STATE_DIR"
CURRENT_STEP="baselane_disk_space_preflight"
if [ -x "$ROOT/scripts/baselane_disk_space_preflight.py" ]; then
  set +e
  timeout --kill-after="${BASELANE_DISK_PREFLIGHT_KILL_AFTER_SECONDS}s" \
    "${BASELANE_DISK_PREFLIGHT_TIMEOUT_SECONDS}s" \
    "$PY" "$ROOT/scripts/baselane_disk_space_preflight.py" \
    --path "real_estate_root=$REAL_ESTATE_ROOT" \
    --path "workspace_root=$ROOT" \
    --min-free-mib "$BASELANE_DISK_PREFLIGHT_MIN_FREE_MIB" \
    --path-timeout-seconds "$BASELANE_DISK_PREFLIGHT_PATH_TIMEOUT_SECONDS" \
    --report "$DISK_PREFLIGHT_REPORT_FILE" >/dev/null
  DISK_PREFLIGHT_RC="$?"
  set -e
	  if [ "$DISK_PREFLIGHT_RC" -eq 0 ]; then
	    DISK_PREFLIGHT_STATUS="ok"
	  else
	    DISK_PREFLIGHT_STATUS="review"
	    MONTHLY_READINESS_STATUS="blocked_disk_space_preflight"
	    LOFTY_PM_PUBLISH_STATUS="review_disk_space_preflight"
	    OWNER_EMAIL_SEND_BLOCKED_REASON="monthly disk preflight is review; free local Dropbox/Windows disk before monthly publish/email"
	    write_lofty_pm_publish_disk_hold_report
	    write_owner_email_packet_disk_hold_report
	    extract_owner_email_packet_fields
	    write_monthly_report 75 "failed" "$CURRENT_STEP"
    refresh_owner_email_send_guard_report
    write_monthly_report 75 "failed" "$CURRENT_STEP"
    trap - EXIT
    echo "[baselane-monthly] local disk preflight blocked scheduled writes; recovery will retry; see $DISK_PREFLIGHT_REPORT_FILE" >&2
    exit 75
	  fi
else
  DISK_PREFLIGHT_STATUS="missing"
fi
fetch_yhome_sold_guard

