      MONTHLY_STATEMENTS_STATUS="ok_dry_run_aligned_owner_gate"
    elif [ "$monthly_statements_dry_run_rc" -eq 2 ]; then
      MONTHLY_STATEMENTS_STATUS="review_dry_run_aligned_owner_gate"
    else
      MONTHLY_STATEMENTS_STATUS="failed_dry_run_aligned_owner_gate"
      exit "$monthly_statements_dry_run_rc"
    fi
  else
    MONTHLY_STATEMENTS_STATUS="skipped_dry_run"
  fi
elif [ ! -x "$ROOT/scripts/baselane_monthly_statements_idempotent.sh" ]; then
  echo "[baselane-monthly] missing executable: $ROOT/scripts/baselane_monthly_statements_idempotent.sh" >&2
  exit 1
else
  set +e
  BASELANE_MONTHLY_YHOME_TRANSITION_RECONCILIATION_CSV="$YHOME_TRANSITION_RECONCILIATION_CSV" \
    "$ROOT/scripts/baselane_monthly_statements_idempotent.sh"
  monthly_statements_rc="$?"
  set -e
  if [ "$monthly_statements_rc" -eq 0 ]; then
    MONTHLY_STATEMENTS_STATUS="ok"
  elif [ "$monthly_statements_rc" -eq 2 ]; then
    MONTHLY_STATEMENTS_STATUS="$($PY - "$MONTHLY_STATEMENTS_IDEMPOTENT_FILE" <<'PY'
import json
import sys
from pathlib import Path
try:
    report = json.loads(Path(sys.argv[1]).read_text(encoding="utf-8"))
except Exception:
    print("review")
else:
    status = str(report.get("status") or "review")
    reason = str(report.get("reason") or "")
    action = str(report.get("action") or "")
    if status == "review" and (
        reason.startswith("aligned-owner-")
        or action in {"auth-baselane", "review-aligned-owner-import", "mortgage-review"}
    ):
        print("review_nonblocking")
    else:
        print(status if status.startswith("review") else "review")
PY
)"
    OWNER_EMAIL_SEND_BLOCKED_REASON="${OWNER_EMAIL_SEND_BLOCKED_REASON:-monthly statement gate needs review before owner email send}"
    echo "[baselane-monthly] monthly statement gate returned review rc=2; continuing downstream artifact refresh with status=$MONTHLY_STATEMENTS_STATUS" >&2
  else
    MONTHLY_STATEMENTS_STATUS="failed"
    exit "$monthly_statements_rc"
  fi
fi
if [ "$BASELANE_MONTHLY_STOP_AFTER_STATEMENTS_GATE" = "1" ]; then
