elif [ -f "$HEMLANE_FINANCIAL_EVIDENCE_SCRIPT" ]; then
  set +e
  timeout --kill-after=15s 180s "$PY" "$HEMLANE_FINANCIAL_EVIDENCE_SCRIPT" \
    --root "$ROOT" --days-back 120 --report "$HEMLANE_FINANCIAL_EVIDENCE_FILE" >/dev/null
  hemlane_evidence_rc="$?"
  set -e
else
  hemlane_evidence_rc=2
fi
if [ "$RUN_DAO_VENDOR_UPSTREAM_NORMALIZATION" = "1" ] \
  && [ "$lawnstarter_evidence_rc" -eq 0 ] \
  && [ "$hemlane_evidence_rc" -eq 0 ] \
  && [ -f "$DAO_VENDOR_PROPERTY_RECONCILIATION_SCRIPT" ]; then
  set +e
  WORKSPACE_ROOT="$ROOT" timeout --kill-after=15s 240s "$PY" "$DAO_VENDOR_PROPERTY_RECONCILIATION_SCRIPT" \
    --lawnstarter-evidence "$LAWNSTARTER_BILLING_EVIDENCE_FILE" \
    --hemlane-evidence "$HEMLANE_FINANCIAL_EVIDENCE_FILE" \
    --native-split-plan "$DAO_VENDOR_NATIVE_SPLIT_PLAN_FILE" \
    --report "$DAO_VENDOR_PROPERTY_RECONCILIATION_FILE" >/dev/null
  dao_vendor_plan_rc="$?"
  set -e
else
  dao_vendor_plan_rc=2
fi
if [ "$dao_vendor_plan_rc" -eq 0 ] \
  && [ "$DRY_RUN" = "0" ] \
  && [ "$BASELANE_MONTHLY_LIVE_ACTIONS_APPROVED" = "1" ]; then
  IFS=$'\t' read -r dao_vendor_digest dao_vendor_ready dao_vendor_guards dao_vendor_splits < <(
    "$PY" - "$DAO_VENDOR_PROPERTY_RECONCILIATION_FILE" <<'PY'
import json
import sys
from pathlib import Path
data = json.loads(Path(sys.argv[1]).read_text(encoding="utf-8"))
print("\t".join(str(value) for value in (
    data.get("plan_digest") or "",
    int(data.get("ready_count") or 0),
    int(data.get("guard_failure_count") or 0),
    int(data.get("native_split_count") or 0),
)))
PY
  )
  if [ "$dao_vendor_guards" -eq 0 ] && [ "$dao_vendor_ready" -gt 0 ]; then
    WORKSPACE_ROOT="$ROOT" timeout --kill-after=15s 240s "$PY" "$DAO_VENDOR_PROPERTY_RECONCILIATION_SCRIPT" \
      --apply --digest "$dao_vendor_digest" \
      --lawnstarter-evidence "$LAWNSTARTER_BILLING_EVIDENCE_FILE" \
      --hemlane-evidence "$HEMLANE_FINANCIAL_EVIDENCE_FILE" \
      --native-split-plan "$DAO_VENDOR_NATIVE_SPLIT_PLAN_FILE" \
      --report "$DAO_VENDOR_PROPERTY_RECONCILIATION_FILE" >/dev/null
  fi
  if [ "$dao_vendor_guards" -eq 0 ] && [ "$dao_vendor_splits" -gt 0 ]; then
    BASELANE_NATIVE_SPLIT_APPLY=1 "$PY" "$DAO_VENDOR_NATIVE_SPLIT_APPLY_SCRIPT" \
      --apply --plan "$DAO_VENDOR_NATIVE_SPLIT_PLAN_FILE" \
      --report "$DAO_VENDOR_NATIVE_SPLIT_APPLY_FILE" >/dev/null
  fi
  WORKSPACE_ROOT="$ROOT" timeout --kill-after=15s 240s "$PY" "$DAO_VENDOR_PROPERTY_RECONCILIATION_SCRIPT" \
    --lawnstarter-evidence "$LAWNSTARTER_BILLING_EVIDENCE_FILE" \
    --hemlane-evidence "$HEMLANE_FINANCIAL_EVIDENCE_FILE" \
    --native-split-plan "$DAO_VENDOR_NATIVE_SPLIT_PLAN_FILE" \
    --report "$DAO_VENDOR_PROPERTY_RECONCILIATION_FILE" >/dev/null
fi

# This source normalization is owned by the monthly OpenClaw cron-network run.
# It refreshes before planning and again after writes, so downstream finance
# truth never consumes the pre-mutation export. Pending rows are deferred.
CURRENT_STEP="nonproperty_category_normalization"
NONPROPERTY_CATEGORY_NORMALIZE_SCRIPT="$ROOT/scripts/baselane_nonproperty_category_normalize.sh"
NONPROPERTY_CATEGORY_NORMALIZATION_STATUS="skipped_missing_script"
NONPROPERTY_CATEGORY_NORMALIZATION_TIMEOUT_SECONDS="${BASELANE_NONPROPERTY_CATEGORY_NORMALIZATION_TIMEOUT_SECONDS:-1800}"
if [ "$RUN_NONPROPERTY_CATEGORY_NORMALIZATION" != "1" ]; then
  NONPROPERTY_CATEGORY_NORMALIZATION_STATUS="skipped_resume_from_verified_export"
elif [ -x "$NONPROPERTY_CATEGORY_NORMALIZE_SCRIPT" ]; then
  set +e
  BASELANE_NONPROPERTY_CATEGORY_LIVE_APPROVED="$(
    if [ "$DRY_RUN" = "0" ] && [ "$BASELANE_MONTHLY_LIVE_ACTIONS_APPROVED" = "1" ]; then
      printf '1'
    else
      printf '0'
    fi
  )" \
  BASELANE_NONPROPERTY_CATEGORY_PLAN_PREFIX="$NONPROPERTY_CATEGORY_PLAN_PREFIX" \
  WORKSPACE_ROOT="$ROOT" \
  timeout --kill-after=30s "${NONPROPERTY_CATEGORY_NORMALIZATION_TIMEOUT_SECONDS}s" \
    "$NONPROPERTY_CATEGORY_NORMALIZE_SCRIPT" >/dev/null
  nonproperty_category_normalization_rc="$?"
  set -e
  if [ "$nonproperty_category_normalization_rc" -eq 0 ]; then
    NONPROPERTY_CATEGORY_NORMALIZATION_STATUS="ok"
  elif [ "$nonproperty_category_normalization_rc" -eq 75 ]; then
    NONPROPERTY_CATEGORY_NORMALIZATION_STATUS="locked"
    echo "[baselane-monthly] Non-Property category normalization is locked by another source writer" >&2
    exit 75
  else
    NONPROPERTY_CATEGORY_NORMALIZATION_STATUS="review"
    echo "[baselane-monthly] settled Non-Property category normalization is incomplete" >&2
    exit "$nonproperty_category_normalization_rc"
  fi
fi

