    baselane_auth_preflight_status="$($PY - "$BASELANE_AUTH_RECOVERY_REPORT_FILE" <<'PY'
import json
import sys
from pathlib import Path
try:
    print(json.loads(Path(sys.argv[1]).read_text(encoding="utf-8")).get("status") or "review")
except Exception:
