import json
import sys
from pathlib import Path
try:
    print(json.loads(Path(sys.argv[1]).read_text(encoding="utf-8")).get("status") or "review")
except Exception:
    print("report_unreadable")
PY
)"
    if [ "$baselane_auth_preflight_rc" -ne 0 ] || [ "$baselane_auth_preflight_status" != "ok" ]; then
