      "$PY" - "$MONTHLY_FINANCE_TRUTH_REFRESH_FILE" "$RUN_MONTH" "$DRY_RUN" "$baselane_auth_preflight_exit" "$BASELANE_AUTH_RECOVERY_REPORT_FILE" <<'PY'
import datetime as dt
import json
import sys
from pathlib import Path

report_path = Path(sys.argv[1])
run_month = sys.argv[2]
dry_run = sys.argv[3] == "1"
exit_code = int(sys.argv[4])
auth_report_path = Path(sys.argv[5])
try:
    auth_report = json.loads(auth_report_path.read_text(encoding="utf-8"))
except Exception as exc:
    auth_report = {"status": "report_unreadable", "error": str(exc)}
login_wait_path = report_path.parent / "baselane_login_wait_report.json"
try:
    login_wait = json.loads(login_wait_path.read_text(encoding="utf-8"))
except Exception:
    login_wait = {}
login_wait_reason = str(login_wait.get("reason") or "").strip()
login_wait_recaptcha = (
    login_wait_reason == "baselane_login_recaptcha_required"
    or login_wait.get("recaptcha_present") is True
)
auth_issue = str(auth_report.get("issue_summary") or "").strip()
auth_action = str(auth_report.get("next_action") or "").strip()
auth_reason = str(auth_report.get("manual_auth_reason") or auth_report.get("reason") or "").strip()
auth_text = " ".join(part for part in (auth_issue, auth_action, auth_reason) if part).lower()
auth_or_appcheck_blocked = any(
    marker in auth_text
    for marker in ("recaptcha", "captcha", "appcheck", "login", "missing cookie", "unauthorized", "auth")
)
if login_wait_recaptcha:
    issue_summary = "Baselane reCAPTCHA is visible in the CDP login tab; monthly finance-truth cannot safely run."
elif auth_issue:
    issue_summary = auth_issue
elif auth_or_appcheck_blocked:
    issue_summary = "Baselane auth/appcheck blocked monthly finance-truth auth preflight."
else:
    issue_summary = "Baselane auth preflight blocked monthly finance-truth refresh."
if login_wait_recaptcha:
    next_action = str(login_wait.get("next_action") or "").strip() or (
        "Solve Baselane reCAPTCHA in the visible CDP tab, then rerun "
        f"`RUN_MONTH={run_month} bash scripts/baselane_monthly_finance_truth_refresh.sh` "
        "or `bash scripts/baselane_financials_post_auth_resume.sh` before downstream "
        "CF/FINANCIALS/Lofty/Discord/email outputs."
    )
elif auth_or_appcheck_blocked:
    next_action = (
        f"{issue_summary} Then rerun `RUN_MONTH={run_month} bash scripts/baselane_monthly_finance_truth_refresh.sh` "
        "or `bash scripts/baselane_financials_post_auth_resume.sh` before downstream "
        "CF/FINANCIALS/Lofty/Discord/email outputs."
    )
elif auth_action:
    next_action = auth_action
else:
    next_action = (
        f"Review {auth_report_path}, complete Baselane auth if needed, then rerun "
        f"`RUN_MONTH={run_month} bash scripts/baselane_monthly_finance_truth_refresh.sh` before downstream "
        "CF/FINANCIALS/Lofty/Discord/email outputs."
    )
summary_parts = [
    f"status={auth_report.get('status') or 'unknown'}",
    f"next_action={next_action}",
]
if auth_report.get("reason"):
    summary_parts.append(f"reason={auth_report.get('reason')}")
if auth_report.get("manual_auth_reason"):
    summary_parts.append(f"manual_auth_reason={auth_report.get('manual_auth_reason')}")
if login_wait_reason:
    summary_parts.append(f"baselane_login_wait_reason={login_wait_reason}")
if login_wait_recaptcha:
    summary_parts.append("baselane_login_wait_recaptcha_present=true")
if issue_summary:
    summary_parts.append(f"issue_summary={issue_summary}")
report = {
    "job": "baselane-monthly-finance-truth-refresh",
    "generated_at": dt.datetime.now(dt.UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z"),
    "status": "failed",
    "run_month": run_month,
    "dry_run": dry_run,
    "failed_step": "baselane_auth_preflight",
