    raise SystemExit(1)
for row in rows:
    if not row.get("property_path") or not row.get("status"):
        raise SystemExit(1)
    if row["status"] in {"existing", "created", "would_create"}:
        draft = Path(row.get("draft_path") or "")
        if not draft.is_file() or draft.stat().st_size == 0:
            raise SystemExit(1)
PY
