except ImportError:
    import re

    def normalize_exclusion(value):
        text = str(value).lower()
        text = re.sub(r"\blfty\d+\b", " ", text)
        text = text.replace("&", "and")
        text = re.sub(r"[^a-z0-9]+", " ", text)
        text = re.sub(r"\bavenue\b", "ave", text)
        text = re.sub(r"\bstreet\b", "st", text)
        text = re.sub(r"\s+", " ", text)
        return text.strip()
from lofty_property_paths import public_dir_for_property, resolve_property_path

root = Path(os.environ["ROOT"])
index_csv = Path(os.environ["MONTHLY_INDEX_CSV"])
updates_guard = Path(os.environ["UPDATES_GUARD"]) if os.environ.get("UPDATES_GUARD") else None
live_guard = Path(os.environ["LIVE_GUARD"]) if os.environ.get("LIVE_GUARD") else None
audit_file = Path(os.environ["GUARD_AUDIT_FILE"])
yhome_csv = Path(os.environ["YHOME_TRANSITION_RECONCILIATION_CSV"]) if os.environ.get("YHOME_TRANSITION_RECONCILIATION_CSV") else None
transfer_reconciliation_file = Path(os.environ["TRANSFER_RECONCILIATION_FILE"]) if os.environ.get("TRANSFER_RECONCILIATION_FILE") else None
property_reconciliation_holds_file = Path(os.environ["PROPERTY_RECONCILIATION_HOLDS_FILE"]) if os.environ.get("PROPERTY_RECONCILIATION_HOLDS_FILE") else None
run_started_at = str(os.environ.get("RUN_STARTED_AT") or "").strip()
issues = []
records = []
externally_excluded_records = []
source_held_records = []
yhome_guard = {"status": "not_checked", "path": str(yhome_csv) if yhome_csv else None, "excluded_count": 0}
manual_exclusions = []
GUARD_TIMEOUT_SECONDS = 30
SAFE_MONTHLY_CRON_DRY_RUN_COMMAND = (
    "DRY_RUN=1 SEND_OWNER_EMAILS=0 PUBLISH_LOFTY_PM_UPDATES=0 "
    "RUN_LOFTY_GUARDED_APPLY=1 APPLY_LOFTY_GUARDED_UPDATES=0 bash scripts/baselane_financials_monthly_cron.sh"
)

def normalize_index_status(value):
    text = str(value or "").strip().lower()
    text = re.sub(r"[^a-z0-9]+", "_", text)
    text = re.sub(r"_+", "_", text).strip("_")
    if not text:
        return ""
    tokens = {token for token in text.split("_") if token}
    if "delisted" in tokens:
        return "skipped_delisted" if text.startswith("skipped") else "delisted"
    if "sold" in tokens:
        return "skipped_sold" if text.startswith("skipped") else "sold"
    if "closed" in tokens:
        return "skipped_closed" if text.startswith("skipped") else "closed"
    return text

def is_active_index_status(value):
    return normalize_index_status(value) in {"created", "existing", "would_create"}

def first_error_line(stderr):
    text = str(stderr or "").strip()
    if not text:
        return None
    first_line = next((line.strip() for line in text.splitlines() if line.strip()), "")
    return first_line[:300] or None

def append_guard_issue(kind, path, check, issue_text=None):
    error = first_error_line(check.get("stderr") if isinstance(check, dict) else None)
    detail = f"{kind} guard failed: {path}"
    if issue_text:
        detail = issue_text
    if error:
        detail = f"{detail} :: {error}"
    issues.append(detail)

def parse_utc(value):
    text = str(value or "").strip()
    if not text:
        return None
    try:
        parsed = dt.datetime.fromisoformat(text.replace("Z", "+00:00"))
    except ValueError:
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=dt.timezone.utc)
    return parsed.astimezone(dt.timezone.utc)

def reconciliation_hold_guard(reason_code, reason):
    property_name = "9 Country Club Ln N"
    return {
        "source": "property_reconciliation_hold",
        "property_name": property_name,
        "normalized_property": normalize_exclusion(property_name),
        "exclude_reason": reason,
        "source_clean_status": "held",
        "review_rows_remaining": 1,
        "high_priority_unresolved_sum": None,
        "issue_codes": [reason_code],
        "live_state_verified": False,
        "source_digest": None,
    }

def load_source_held_guards():
    guards = []
    if transfer_reconciliation_file and transfer_reconciliation_file.is_file():
        try:
            transfer = json.loads(transfer_reconciliation_file.read_text(encoding="utf-8"))
        except Exception:
            transfer = {}
        for detail in transfer.get("property_cash_review_details") or []:
            if not isinstance(detail, dict):
                continue
            property_name = str(detail.get("property") or detail.get("property_name") or "").strip()
            if not property_name:
                continue
            guards.append({
                "source": "property_cash_review",
                "property_name": property_name,
                "normalized_property": normalize_exclusion(property_name),
                "exclude_reason": "property source-cash/cash-alignment review is held; suppress live update/email guard until source-clean",
                "source_clean_status": detail.get("source_clean_status"),
                "review_rows_remaining": detail.get("property_cash_review_unreviewed_group_count"),
                "high_priority_unresolved_sum": detail.get("property_cash_review_high_priority_unresolved_sum"),
            })

    if not property_reconciliation_holds_file or not property_reconciliation_holds_file.is_file():
        guards.append(reconciliation_hold_guard(
            "property_reconciliation_hold_report_missing",
            "The current-run 9 Country Club reconciliation hold report is missing; retain the property hold without blocking other properties.",
        ))
        return guards
    try:
        hold_report = json.loads(property_reconciliation_holds_file.read_text(encoding="utf-8"))
    except Exception:
        guards.append(reconciliation_hold_guard(
            "property_reconciliation_hold_report_unreadable",
            "The current-run 9 Country Club reconciliation hold report is unreadable; retain the property hold without blocking other properties.",
        ))
        return guards

    generated_at = parse_utc(hold_report.get("generated_at"))
    started_at = parse_utc(run_started_at)
    if generated_at is None or started_at is None or generated_at < started_at:
        guards.append(reconciliation_hold_guard(
            "property_reconciliation_hold_report_stale",
            "The 9 Country Club reconciliation hold report is not current for this run; retain the property hold without blocking other properties.",
        ))
        return guards

    status = str(hold_report.get("status") or "").strip().lower()
    held_properties = hold_report.get("held_properties")
    if status == "ok" and int(hold_report.get("held_property_count") or 0) == 0:
        return guards
    if status != "held" or not isinstance(held_properties, list) or not held_properties:
        guards.append(reconciliation_hold_guard(
            "property_reconciliation_hold_report_invalid",
            "The 9 Country Club reconciliation hold report is invalid; retain the property hold without blocking other properties.",
        ))
        return guards
    for detail in held_properties:
        if not isinstance(detail, dict):
            continue
        property_name = str(detail.get("property") or detail.get("property_name") or "").strip()
        if not property_name:
            continue
        guards.append({
            "source": "property_reconciliation_hold",
            "property_name": property_name,
            "normalized_property": normalize_exclusion(property_name),
            "exclude_reason": str(detail.get("hold_reason") or "Property reconciliation is held; suppress live update and owner email until source-clean."),
            "source_clean_status": "held",
            "review_rows_remaining": detail.get("issue_count"),
            "high_priority_unresolved_sum": None,
            "issue_codes": detail.get("issue_codes") if isinstance(detail.get("issue_codes"), list) else [],
            "live_state_verified": detail.get("live_state_verified") is True,
            "source_digest": detail.get("source_digest"),
        })
    return guards

def load_current_only_verified():
    path = root / "reports" / "lofty_listing_update_cleanup_queue.local-live-verify.json"
    if not path.is_file():
        return {}
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return {}
    if payload.get("status") != "ok" or int(payload.get("issue_count") or 0) != 0:
        return {}
    records = payload.get("records") if isinstance(payload.get("records"), list) else []
    verified = {}
    for record in records:
        if not isinstance(record, dict) or record.get("ok") is not True:
            return {}
        property_id = str(record.get("lofty_property_id") or "").strip()
        if not property_id or record.get("financial_summary_verified") is not True:
            return {}
        verified[property_id] = record
    if int(payload.get("target_count") or 0) != len(verified) or int(payload.get("ok_count") or 0) != len(verified):
        return {}
    return verified

if not index_csv.is_file():
    issues.append(f"monthly index missing: {index_csv}")
else:
    current_only_verified = load_current_only_verified()
    live_update_capture_path = root / "reports" / "baselane_financials_monthly_live_update_capture.json"
    live_update_current_only_ids = set()
    live_update_current_only_by_updates_md = {}
    try:
        live_update_capture = json.loads(live_update_capture_path.read_text(encoding="utf-8"))
        for live_record in live_update_capture.get("records") or []:
            if isinstance(live_record, dict) and live_record.get("status") == "guard_ok_current_only":
                property_id = str(live_record.get("lofty_property_id") or "")
                live_update_current_only_ids.add(property_id)
                updates_md_value = str(live_record.get("updates_md") or "")
                if property_id and updates_md_value:
                    live_update_current_only_by_updates_md[updates_md_value] = property_id
    except Exception:
        pass
    exclusion_guards, yhome_guard, manual_exclusions = monthly_exclusion_guards(yhome_csv, DEFAULT_MANUAL_EXCLUDED_PROPERTIES)
    source_held_guards = load_source_held_guards()
    with index_csv.open(newline="", encoding="utf-8") as handle:
      rows = list(csv.DictReader(handle))
    for prop in rows:
        if not is_active_index_status(prop.get("status")):
            continue
        property_path_value = prop.get("property_path") or ""
        if not property_path_value:
            continue
        property_path, path_resolution = resolve_property_path(Path(property_path_value))
        exclusion = match_exclusion_guard(property_path, exclusion_guards)
        if exclusion:
            externally_excluded_records.append({
                "status": "excluded_no_live_update_or_email",
                "property_name": property_path.name,
                "property_path": str(property_path),
                "exclude_source": exclusion.get("source"),
                "exclude_reason": exclusion.get("exclude_reason"),
                "matched_exclusion_property": exclusion.get("property_name"),
                "yhome_column_b": exclusion.get("yhome_column_b"),
                **path_resolution,
            })
            continue
        source_hold = match_exclusion_guard(property_path, source_held_guards)
        if source_hold:
            source_held_records.append({
                "status": (
                    "held_property_reconciliation"
                    if source_hold.get("source") == "property_reconciliation_hold"
                    else "held_source_cash_review"
                ),
                "property_name": property_path.name,
                "property_path": str(property_path),
                "hold_source": source_hold.get("source"),
                "hold_reason": source_hold.get("exclude_reason"),
                "matched_hold_property": source_hold.get("property_name"),
                "source_clean_status": source_hold.get("source_clean_status"),
                "review_rows_remaining": source_hold.get("review_rows_remaining"),
                "high_priority_unresolved_sum": source_hold.get("high_priority_unresolved_sum"),
                "issue_codes": source_hold.get("issue_codes"),
                "live_state_verified": source_hold.get("live_state_verified"),
                "source_digest": source_hold.get("source_digest"),
                **path_resolution,
            })
            continue
        public_dir = public_dir_for_property(property_path)
        updates_path = public_dir / "00 - README & Property Snapshot" / "UPDATES.md"
        financials_path = public_dir / "00 - README & Property Snapshot" / "FINANCIALS.md"
        record = {
            "property_name": property_path.name,
            "property_path": str(property_path),
            "updates_md": str(updates_path),
            "financials_md": str(financials_path),
            "checks": {},
            **path_resolution,
        }
        if not updates_path.is_file():
            record["checks"]["updates"] = {"status": "missing"}
            issues.append(f"UPDATES.md missing: {updates_path}")
        elif not updates_guard or not updates_guard.is_file():
            record["checks"]["updates"] = {"status": "guard_missing"}
            issues.append(f"updates guard missing: {updates_guard}")
        else:
            try:
                result = subprocess.run([sys.executable, str(updates_guard), "check", str(updates_path)], capture_output=True, text=True, timeout=GUARD_TIMEOUT_SECONDS)
                record["checks"]["updates"] = {"status": "ok" if result.returncode == 0 else "failed", "return_code": result.returncode, "stderr": result.stderr[-1000:]}
            except subprocess.TimeoutExpired:
                result = None
                record["checks"]["updates"] = {"status": "failed", "return_code": 124, "stderr": f"guard command timed out after {GUARD_TIMEOUT_SECONDS}s", "timed_out": True}
            if result is None:
                append_guard_issue("UPDATES", updates_path, record["checks"]["updates"], f"UPDATES guard timed out: {updates_path}")
            elif result.returncode != 0:
                property_id = live_update_current_only_by_updates_md.get(str(updates_path), "")
                if not property_id and live_update_current_only_ids:
                    for item in live_update_current_only_ids:
                        if item in current_only_verified:
                            verified_name = str(current_only_verified[item].get("property_name") or "")
                            if verified_name and (verified_name == property_path.name or verified_name in property_path.name or property_path.name in verified_name):
                                property_id = item
                                break
                if property_id and property_id in current_only_verified:
                    record["checks"]["updates"] = {
                        **record["checks"]["updates"],
                        "status": "ok",
                        "guard_mode": "current_only_live_listing_verified",
                        "live_update_capture": "guard_ok_current_only",
                        "current_only_listing_verify": current_only_verified[property_id],
                    }
                else:
                    append_guard_issue("UPDATES", updates_path, record["checks"]["updates"])
        if not financials_path.is_file():
            record["checks"]["financials"] = {"status": "missing"}
            issues.append(f"FINANCIALS.md missing: {financials_path}")
        else:
            record["checks"]["financials"] = {
                "status": "ok",
                "guard_mode": "local_document_exists",
                "live_field_guard": "baselane_financials_monthly_live_financial_capture",
                "note": "FINANCIALS.md is local Dropbox documentation; Lofty live financial field drift is guarded by the live financial capture report, not by requiring local markdown to equal Lofty sparse live fields.",
            }
        records.append(record)
guard_failures = []
for record in records:
    for section, label in (("updates", "UPDATES"), ("financials", "FINANCIALS")):
        check = record.get("checks", {}).get(section, {})
        if check.get("status") != "failed":
            continue
        target_key = "updates_md" if section == "updates" else "financials_md"
        guard_failures.append({
            "property_name": record.get("property_name"),
            "property_path": record.get("property_path"),
            "target": label,
            "target_path": record.get(target_key),
            "return_code": check.get("return_code"),
            "timed_out": bool(check.get("timed_out")),
            "first_error": first_error_line(check.get("stderr")),
            "next_action": (
                f"Review the local {label}.md guard stderr for this property; if Lofty live evidence is stale, "
                f"rerun `{SAFE_MONTHLY_CRON_DRY_RUN_COMMAND}` with an authenticated Lofty tab. "
                "Do not enable owner email or guarded apply until this audit is ok."
            ),
        })
audit = {
    "status": "ok" if not issues else "review",
    "issue_count": len(issues),
    "issues": issues[:50],
    "guard_failure_count": len(guard_failures),
    "guard_failures": guard_failures[:50],
    "property_count": len(records),
    "externally_excluded_count": len(externally_excluded_records),
    "externally_excluded_records": externally_excluded_records,
    "source_held_count": len(source_held_records),
    "source_held_records": source_held_records,
    "excluded_property_names": [record["property_name"] for record in externally_excluded_records],
    "yhome_transition_guard": yhome_guard,
    "manual_excluded_property_names": [record["property_name"] for record in manual_exclusions],
    "records": records,
}
audit_file.write_text(json.dumps(audit, indent=2, sort_keys=True) + "\n", encoding="utf-8")
raise SystemExit(0 if not issues else 2)
PY
