    --updates-guard "$UPDATES_GUARD" \
    --live-guard "$LIVE_GUARD" \
    --report "$GUARDED_APPLY_FILE" \
	    --yhome-transition-csv "$YHOME_TRANSITION_RECONCILIATION_CSV" \
	    --transfer-reconciliation-report "$TRANSFER_RECONCILIATION_FILE" \
	    --financial-approval-manifest "$FINANCIAL_APPROVAL_MANIFEST" \
	    --update-approval-manifest "$UPDATE_APPROVAL_MANIFEST" \
	    --listing-update-policy "$ROOT/config/lofty_listing_update_policy.json" \
	    --apply
  guarded_apply_rc="$?"
  set -e
  if [ "$guarded_apply_rc" -eq 0 ]; then
    LOFTY_GUARDED_APPLY_STATUS="ok"
  elif [ "$guarded_apply_rc" -eq 2 ]; then
    LOFTY_GUARDED_APPLY_STATUS="review_required"
  else
    if [ "$guarded_apply_rc" -eq 124 ] || [ "$guarded_apply_rc" -eq 137 ]; then
      LOFTY_GUARDED_APPLY_STATUS="failed_timeout_required"
      write_guarded_apply_skipped_report "$LOFTY_GUARDED_APPLY_STATUS" "guarded apply timed out after ${GUARDED_APPLY_TIMEOUT_SECONDS}s"
    fi
    if [ "$REQUIRE_GUARDED_MONTHLY_APPLY" = "1" ]; then
      if [ "$guarded_apply_rc" -ne 124 ] && [ "$guarded_apply_rc" -ne 137 ]; then
        LOFTY_GUARDED_APPLY_STATUS="failed_required"
      fi
      exit "$guarded_apply_rc"
    else
      LOFTY_GUARDED_APPLY_STATUS="failed_not_required"
    fi
  fi
fi

