	    exit "$tenant_ledger_guard_rc"
	  fi
	fi

run_owner_review_gate "monthly_owner_review_gate"

CURRENT_STEP="monthly_readiness_report"
refresh_monthly_readiness_report
monthly_readiness_blocked_reason() {
  if [ -n "$MONTHLY_READINESS_PRIMARY_BLOCKER" ]; then
    printf 'monthly readiness owner_email_allowed=false; primary=%s; actionable=%s' "$MONTHLY_READINESS_PRIMARY_BLOCKER" "$MONTHLY_READINESS_ACTIONABLE_BLOCKER_COUNT"
  else
    printf 'monthly readiness owner_email_allowed=false; actionable=%s' "$MONTHLY_READINESS_ACTIONABLE_BLOCKER_COUNT"
  fi
}
discord_all_send_plan_blocked_reason() {
  if [ ! -s "$MONTHLY_DISCORD_ALL_SEND_PLAN_VALIDATION_FILE" ]; then
    printf 'Discord all-property send plan validation missing; refusing owner email before complete Discord review coverage'
    return
  fi
  $PY - "$MONTHLY_DISCORD_ALL_SEND_PLAN_VALIDATION_FILE" <<'PY'
import json
import sys
from pathlib import Path

try:
    data = json.loads(Path(sys.argv[1]).read_text(encoding="utf-8"))
except Exception as exc:
    print(f"Discord all-property send plan validation unreadable: {exc}; refusing owner email")
    raise SystemExit(0)
if data.get("status") in {"ok", "ok_partial"}:
    print("")
    raise SystemExit(0)
parts = [
    f"status={data.get('status')}",
    f"unmapped={int(data.get('unmapped_count') or 0)}",
    f"stale_routes={int(data.get('stale_route_count') or 0)}",
    f"missing_financial_summaries={int(data.get('missing_financial_summary_count') or 0)}",
    f"source_issues={int(data.get('source_issue_count') or 0)}",
]
print("Discord all-property send plan validation not ok; refusing owner email before complete Discord review coverage (" + ", ".join(parts) + ")")
PY
}
if [ "$SEND_OWNER_EMAILS" = "1" ] && [ "$MONTHLY_READINESS_OWNER_EMAIL_ALLOWED" != "1" ]; then
  OWNER_EMAIL_SEND_BLOCKED_REASON="$(monthly_readiness_blocked_reason)"
fi

CURRENT_STEP="monthly_accruals_completeness"
MONTHLY_ACCRUALS_SCRIPT="$ROOT/scripts/baselane_monthly_accruals_cron.sh"
if [ ! -x "$MONTHLY_ACCRUALS_SCRIPT" ]; then
  MONTHLY_ACCRUALS_STATUS="skipped_missing_script"
  if [ "$REQUIRE_MONTHLY_ACCRUAL_COMPLETENESS" = "1" ]; then
    OWNER_EMAIL_SEND_BLOCKED_REASON="${OWNER_EMAIL_SEND_BLOCKED_REASON:-monthly accrual completeness script missing}"
  fi
else
  set +e
  BASELANE_MONTHLY_ACCRUALS_MONTH="$RUN_MONTH" \
    BASELANE_MONTHLY_ACCRUALS_DRY_RUN="$DRY_RUN" \
    BASELANE_MONTHLY_ACCRUALS_REPORTING_CUTOFF_DATE="$REPORTING_CUTOFF_DATE" \
    BASELANE_MONTHLY_ACCRUALS_REVIEW_MARKDOWN="$MONTHLY_ACCRUALS_REVIEW_MARKDOWN_FILE" \
    "$MONTHLY_ACCRUALS_SCRIPT" >/dev/null
  monthly_accruals_rc="$?"
  set -e
  if [ "$monthly_accruals_rc" -eq 0 ]; then
    MONTHLY_ACCRUALS_STATUS="ok"
  else
    MONTHLY_ACCRUALS_STATUS="failed"
    if [ "$REQUIRE_MONTHLY_ACCRUAL_COMPLETENESS" = "1" ]; then
      exit "$monthly_accruals_rc"
    fi
  fi
fi

if [ -f "$MONTHLY_ACCRUALS_REPORT_FILE" ]; then
  IFS=$'\t' read -r \
    MONTHLY_ACCRUALS_MISSING_COUNT \
    MONTHLY_ACCRUALS_AMOUNT_MISMATCH_COUNT \
    MONTHLY_ACCRUALS_BLOCKED_FIRST_DAY_PM_FEE_COUNT \
    MONTHLY_ACCRUALS_ACTIVE_WITHOUT_TEMPLATE_COUNT \
    MONTHLY_ACCRUALS_ACTIVE_WITHOUT_FIXED_REQUIREMENT_COUNT \
    MONTHLY_ACCRUALS_BLOCKING_GAP_ACTION_COUNT \
    MONTHLY_ACCRUALS_MISSING_FIXED_COVERAGE_COUNT \
    MONTHLY_ACCRUALS_UNAPPROVED_PM_FEE_BASIS_GAP_COUNT < <(
      $PY - "$MONTHLY_ACCRUALS_REPORT_FILE" <<'PY'
import json
import sys
from pathlib import Path

try:
    data = json.loads(Path(sys.argv[1]).read_text(encoding="utf-8"))
