      $PY - "$TRANSFER_RECONCILIATION_FILE" "$RUN_STARTED_AT" <<'PY'
import json
import sys
from datetime import datetime, timezone
from pathlib import Path

try:
    data = json.loads(Path(sys.argv[1]).read_text(encoding="utf-8"))
except Exception:
    data = {}
try:
    generated_at = datetime.fromisoformat(str(data.get("generated_at") or "").replace("Z", "+00:00"))
    started_at = datetime.fromisoformat(str(sys.argv[2] or "").replace("Z", "+00:00"))
    if generated_at.tzinfo is None:
        generated_at = generated_at.replace(tzinfo=timezone.utc)
    if started_at.tzinfo is None:
        started_at = started_at.replace(tzinfo=timezone.utc)
    current_for_run = generated_at.astimezone(timezone.utc) >= started_at.astimezone(timezone.utc)
except (TypeError, ValueError, IndexError):
    current_for_run = False
print("\t".join([
    str(int(data.get("ready_to_send_property_count") or 0)),
    str(int(data.get("held_property_count") or 0)),
    "" if data.get("recommended_send_to_lofty_total") is None else str(data.get("recommended_send_to_lofty_total")),
    "1" if data.get("recommended_send_to_lofty_total_is_final") is True else "0",
    "1" if current_for_run else "0",
]))
PY
    )
fi

