import sys
from pathlib import Path

sys.path.insert(0, sys.argv[2])
from transfer_report_digest import stable_transfer_report_digest

print(stable_transfer_report_digest(Path(sys.argv[1])) or "")
PY
)"
  TELEGRAM_ARGS=(
    --message "$TRANSFER_RECONCILIATION_TELEGRAM_MARKDOWN"
    --transfer-report "$TRANSFER_RECONCILIATION_FILE"
