    --expected-transfer-report-digest "$TRANSFER_RECONCILIATION_EXPECTED_DIGEST"
    --current-run-started-at "$RUN_STARTED_AT"
  )
  if [ "$ALLOW_INFORMATIONAL_TRANSFER_RECONCILIATION_TELEGRAM" = "1" ]; then
    TELEGRAM_ARGS+=(--allow-informational-report)
  fi
  if [ "$ALLOW_BLOCKED_TRANSFER_RECONCILIATION_TELEGRAM" = "1" ]; then
    TELEGRAM_ARGS+=(--allow-blocked-report)
  fi
  if [ "$ALLOW_REVIEW_TRANSFER_RECONCILIATION_TELEGRAM" = "1" ] && [ "$DRY_RUN" = "1" ]; then
    TELEGRAM_ARGS+=(--allow-review-report)
  fi
  if [ "$DRY_RUN" = "1" ]; then
    TELEGRAM_ARGS+=(--dry-run)
  elif [ "$TRANSFER_RECONCILIATION_CURRENT_FOR_RUN" != "1" ]; then
    TELEGRAM_ARGS+=(--dry-run)
    TRANSFER_RECONCILIATION_TELEGRAM_STATUS="blocked_not_current"
  elif [ "$TRANSFER_RECONCILIATION_STATUS" = "blocked_source_not_clean" ] \
    && [ "$ALLOW_BLOCKED_TRANSFER_RECONCILIATION_TELEGRAM" = "1" ]; then
    TELEGRAM_ARGS+=(--send)
    TRANSFER_RECONCILIATION_TELEGRAM_STATUS="blocked_informational"
  elif [ "$TRANSFER_RECONCILIATION_STATUS" != "ok" ] || [ "$TRANSFER_RECONCILIATION_RECOMMENDED_TOTAL_IS_FINAL" != "1" ]; then
    TELEGRAM_ARGS+=(--dry-run)
    TRANSFER_RECONCILIATION_TELEGRAM_STATUS="blocked_not_final"
  else
    TELEGRAM_ARGS+=(--send)
  fi
  set +e
  $PY "$TRANSFER_RECONCILIATION_TELEGRAM_SCRIPT" "${TELEGRAM_ARGS[@]}" >/dev/null
  transfer_telegram_rc="$?"
  set -e
  if [ "$transfer_telegram_rc" -eq 0 ]; then
    if [ "$DRY_RUN" = "1" ]; then
      TRANSFER_RECONCILIATION_TELEGRAM_STATUS="ok_dry_run"
    elif [ "$TRANSFER_RECONCILIATION_TELEGRAM_STATUS" != "blocked_not_final" ] \
      && [ "$TRANSFER_RECONCILIATION_TELEGRAM_STATUS" != "blocked_not_current" ] \
      && [ "$TRANSFER_RECONCILIATION_TELEGRAM_STATUS" != "blocked_informational" ]; then
      TRANSFER_RECONCILIATION_TELEGRAM_STATUS="ok"
    fi
  else
    TRANSFER_RECONCILIATION_TELEGRAM_STATUS="failed"
    exit "$transfer_telegram_rc"
  fi
fi

