    --sent-state-file "$EMAIL_SENT_STATE_FILE"
    --guild-test-post-report "$GUILD_TEST_POST_REPORT_FILE"
    --transfer-reconciliation-report "$TRANSFER_RECONCILIATION_FILE"
  )
  if [ -f "$ROOT/config/lofty_listing_update_policy.json" ]; then
    PUBLISH_ARGS+=(--listing-update-policy "$ROOT/config/lofty_listing_update_policy.json")
  fi
  if [ "$REQUIRE_GUILD_TEST_POST_BEFORE_OWNER_EMAIL" = "1" ]; then
    PUBLISH_ARGS+=(--require-guild-test-post-before-email)
  fi
  if [ -s "$YHOME_TRANSITION_RECONCILIATION_CSV" ]; then
    PUBLISH_ARGS+=(--yhome-transition-csv "$YHOME_TRANSITION_RECONCILIATION_CSV")
  fi
  if [ -f "$LOFTY_PM_PORTFOLIO_MAP" ]; then
    PUBLISH_ARGS+=(--portfolio-map "$LOFTY_PM_PORTFOLIO_MAP")
  fi
  if [ -f "$LOFTY_PM_SKILL_MAP" ]; then
    PUBLISH_ARGS+=(--skill-map "$LOFTY_PM_SKILL_MAP")
  fi
  if [ "$APPLY_LOFTY_LIVE_FINANCIAL_CORRECTIONS" = "1" ] && [ -f "$LOFTY_PM_FINANCIAL_PATCH_SCRIPT" ]; then
    PUBLISH_ARGS+=(--live-financial-corrective --financial-patch-script "$LOFTY_PM_FINANCIAL_PATCH_SCRIPT")
  fi
  if [ -f "$LIVE_FINANCIAL_CAPTURE_FILE" ]; then
    PUBLISH_ARGS+=(--live-financial-capture-report "$LIVE_FINANCIAL_CAPTURE_FILE")
  fi
  if [ -f "$LOFTY_PM_PAYLOAD_BUILDER_SCRIPT" ]; then
    PUBLISH_ARGS+=(--payload-builder-script "$LOFTY_PM_PAYLOAD_BUILDER_SCRIPT")
  fi
  if [ -f "$LOFTY_PM_SAVE_SEND_SCRIPT" ]; then
    PUBLISH_ARGS+=(--save-send-script "$LOFTY_PM_SAVE_SEND_SCRIPT")
  fi
  if [ -f "$REVIEW_CANDIDATE_PACKET_FILE" ]; then
    PUBLISH_ARGS+=(--review-candidate-packet-report "$REVIEW_CANDIDATE_PACKET_FILE")
  fi
  if [ -f "$RENT_ROLL_SOURCE_FILE" ]; then
    PUBLISH_ARGS+=(--rent-roll-source-report "$RENT_ROLL_SOURCE_FILE")
  fi
  if [ -f "$RENT_ROLL_OCCUPANCY_SUMMARY_FILE" ]; then
    PUBLISH_ARGS+=(--rent-roll-occupancy-summary-csv "$RENT_ROLL_OCCUPANCY_SUMMARY_FILE")
  fi
  if [ -f "$LOFTY_LIVE_PROPERTIES_REPORT_FILE" ]; then
    PUBLISH_ARGS+=(--lofty-live-properties-report "$LOFTY_LIVE_PROPERTIES_REPORT_FILE")
  fi
  if [ "$PUBLISH_LOFTY_PM_UPDATES" != "1" ]; then
    OWNER_EMAIL_SEND_BLOCKED_REASON="${OWNER_EMAIL_SEND_BLOCKED_REASON:-PUBLISH_LOFTY_PM_UPDATES disabled}"
  elif [ "$DRY_RUN" != "1" ] && [ "$MONTHLY_LIVE_PUBLISH_ALLOWED" = "1" ]; then
    PUBLISH_ARGS+=(--apply)
    if [ "$SEND_OWNER_EMAILS" != "1" ]; then
      OWNER_EMAIL_SEND_BLOCKED_REASON="SEND_OWNER_EMAILS disabled"
    elif [ "$MONTHLY_READINESS_OWNER_EMAIL_ALLOWED" != "1" ]; then
      OWNER_EMAIL_SEND_BLOCKED_REASON="monthly readiness allows clean-property listing publish but does not allow owner email send"
    elif [ -f "$EMAIL_SENT_STATE_FILE" ] && [ "$(cat "$EMAIL_SENT_STATE_FILE" 2>/dev/null || true)" = "$RUN_MONTH" ]; then
      OWNER_EMAIL_SEND_BLOCKED_REASON="owner emails already sent for $RUN_MONTH"
    else
      OWNER_EMAIL_SEND_REQUESTED="1"
    fi
  elif [ "$SEND_OWNER_EMAILS" = "1" ] && [ -z "$OWNER_EMAIL_SEND_BLOCKED_REASON" ]; then
    OWNER_EMAIL_SEND_BLOCKED_REASON="monthly readiness did not allow owner email send (status=$MONTHLY_READINESS_STATUS, owner_email_allowed=$MONTHLY_READINESS_OWNER_EMAIL_ALLOWED, primary=${MONTHLY_READINESS_PRIMARY_BLOCKER:-none}, actionable=$MONTHLY_READINESS_ACTIONABLE_BLOCKER_COUNT)"
  fi
  if [ -n "$OWNER_EMAIL_SEND_BLOCKED_REASON" ]; then
    PUBLISH_ARGS+=(--owner-email-blocked-reason "$OWNER_EMAIL_SEND_BLOCKED_REASON")
  fi
  if [ "$PUBLISH_LOFTY_PM_UPDATES" != "1" ]; then
    write_lofty_pm_publish_disabled_report
    publish_rc=0
  else
    set +e
    $PY "$LOFTY_PM_PUBLISH_SCRIPT" "${PUBLISH_ARGS[@]}"
    publish_rc="$?"
    set -e
  fi
  if [ "$publish_rc" -eq 0 ]; then
    if [ "$PUBLISH_LOFTY_PM_UPDATES" != "1" ]; then
      LOFTY_PM_PUBLISH_STATUS="ok_not_published"
    elif [ "$DRY_RUN" = "1" ]; then
      LOFTY_PM_PUBLISH_STATUS="ok_dry_run"
    elif [ "$MONTHLY_READINESS_STATUS" = "ok" ]; then
      LOFTY_PM_PUBLISH_STATUS="ok"
    else
      LOFTY_PM_PUBLISH_STATUS="ok_not_applied"
    fi
  elif [ "$publish_rc" -eq 2 ]; then
    if [ "$DRY_RUN" = "1" ]; then
      LOFTY_PM_PUBLISH_STATUS="review_dry_run"
    elif [ "$PUBLISH_LOFTY_PM_UPDATES" != "1" ]; then
      LOFTY_PM_PUBLISH_STATUS="review_not_published"
    else
      LOFTY_PM_PUBLISH_STATUS="review"
    fi
  else
    LOFTY_PM_PUBLISH_STATUS="failed"
    exit "$publish_rc"
	fi
	fi
fi

