CURRENT_STEP="lofty_listing_cleanup_queue"
LOFTY_LISTING_CLEANUP_QUEUE_SCRIPT="$ROOT/scripts/lofty_listing_update_cleanup_queue.py"
if [ "$BUILD_LOFTY_LISTING_CLEANUP_QUEUE" != "1" ]; then
