  $PY - "$LOFTY_LISTING_CLEANUP_QUEUE_FILE" "$RUN_MONTH" "$REPORT_DIR" <<'PY'
import hashlib
import json
import sys
from datetime import datetime, timezone
from pathlib import Path

report = Path(sys.argv[1])
run_month = sys.argv[2]
report_dir = Path(sys.argv[3])
ready_manifest = []
candidate_manifest = []
ready_digest = hashlib.sha256(json.dumps(ready_manifest, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()
queue_digest = hashlib.sha256(
    json.dumps(
        {
            "run_month": run_month,
            "status": "skipped_publish_disabled",
            "ready_cleanup_manifest": ready_manifest,
            "records": [],
        },
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
).hexdigest()
candidate_digest = hashlib.sha256(json.dumps(candidate_manifest, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()
report.parent.mkdir(parents=True, exist_ok=True)
report.write_text(
    json.dumps(
        {
            "generated_at": datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z"),
            "status": "skipped_publish_disabled",
            "run_month": run_month,
            "reason": "PUBLISH_LOFTY_PM_UPDATES disabled; no live listing cleanup queue is needed",
            "mutates_lofty_listing": False,
            "sends_owner_email": False,
            "live_apply_requires_explicit_approval": True,
            "live_apply_preflight_required": True,
            "ready_listing_cleanup_count": 0,
            "record_count": 0,
            "property_count": 0,
            "blocked_count": 0,
            "dry_run_command_count": 0,
            "live_apply_command_requires_explicit_approval_count": 0,
            "ready_cleanup_idempotency_digest": ready_digest,
            "queue_idempotency_digest": queue_digest,
            "ready_cleanup_manifest": ready_manifest,
            "dry_run_commands_file": str(report_dir / "lofty_listing_update_cleanup_queue.dry-run-commands.sh"),
            "live_apply_commands_requires_explicit_approval_file": str(report_dir / "lofty_listing_update_cleanup_queue.live-apply-commands.requires-explicit-approval.sh"),
            "live_apply_approval_env_var": "LOFTY_LISTING_CLEANUP_APPLY_APPROVED",
            "live_apply_approval_env_required_value": "1",
            "live_apply_approval_digest_env_var": "LOFTY_LISTING_CLEANUP_APPLY_DIGEST",
            "live_apply_approval_digest_required_value": ready_digest,
            "live_apply_preflight_command": (
                "LOFTY_LISTING_CLEANUP_DRY_RUN_VERIFY_REPORT="
                f"{report_dir / 'lofty_listing_cleanup_dry_run_verify.json'} "
                "LOFTY_LISTING_CLEANUP_APPLY_PREFLIGHT_REPORT="
                f"{report_dir / 'lofty_listing_update_cleanup_queue.live-apply-preflight.json'} "
                f"LOFTY_LISTING_CLEANUP_APPLY_DIGEST={ready_digest} "
                "python3 scripts/lofty_listing_cleanup_apply_preflight.py "
                "--queue-report reports/lofty_listing_update_cleanup_queue.json "
                "--dry-run-verify-report reports/lofty_listing_cleanup_dry_run_verify.json "
                "--report reports/lofty_listing_update_cleanup_queue.live-apply-preflight.json"
            ),
            "live_apply_preflight_report": str(report_dir / "lofty_listing_update_cleanup_queue.live-apply-preflight.json"),
            "live_apply_dry_run_verify_report": str(report_dir / "lofty_listing_cleanup_dry_run_verify.json"),
            "requires_monthly_financial_summary": True,
            "yhome_transition_column_b_rule_ok": True,
            "excluded_ready_cleanup_count": 0,
            "candidate_update_approval_csv": str(report_dir / "lofty_listing_update_cleanup_queue.candidate-approval.csv"),
            "candidate_update_approval_idempotency_digest": candidate_digest,
            "candidate_update_approval_manifest": candidate_manifest,
            "candidate_update_approval_copy_requires_current_rent_roll": True,
            "candidate_update_approval_copy_requires_explicit_approval": True,
            "candidate_update_approval_copy_command_requires_current_rent_roll_count": 0,
            "candidate_update_approval_copy_commands_requires_current_rent_roll_and_explicit_approval_file": str(
                report_dir / "lofty_listing_update_cleanup_queue.candidate-approval-copy.requires-current-rent-roll-and-explicit-approval.sh"
            ),
            "candidate_update_approval_copy_approval_env_var": "LOFTY_LISTING_UPDATE_APPROVAL_COPY_APPROVED",
            "candidate_update_approval_copy_approval_required_value": "1",
            "candidate_update_approval_copy_current_rent_roll_env_var": "LOFTY_LISTING_UPDATE_APPROVAL_CURRENT_RENT_ROLL_CONFIRMED",
            "candidate_update_approval_copy_current_rent_roll_required_value": "1",
            "candidate_update_approval_copy_digest_env_var": "LOFTY_LISTING_UPDATE_APPROVAL_COPY_DIGEST",
            "candidate_update_approval_copy_digest_required_value": candidate_digest,
            "issue_count": 0,
            "safe_external_effect": False,
            "records": [],
            "issues": [],
        },
        indent=2,
        sort_keys=True,
    )
    + "\n",
    encoding="utf-8",
)
PY
elif [ ! -f "$LOFTY_LISTING_CLEANUP_QUEUE_SCRIPT" ]; then
  LOFTY_LISTING_CLEANUP_QUEUE_STATUS="skipped_missing_script"
