  listing_cleanup_queue_rc="$?"
  set -e
  if [ "$listing_cleanup_queue_rc" -eq 0 ]; then
    LOFTY_LISTING_CLEANUP_QUEUE_STATUS="ok"
  elif [ "$listing_cleanup_queue_rc" -eq 2 ]; then
    LOFTY_LISTING_CLEANUP_QUEUE_STATUS="review"
  else
    LOFTY_LISTING_CLEANUP_QUEUE_STATUS="failed"
    exit "$listing_cleanup_queue_rc"
  fi
fi


