    --telegram-send-report "$TRANSFER_RECONCILIATION_TELEGRAM_SEND_FILE" \
    --report "$MONTHLY_PIPELINE_CANDIDATE_COVERAGE_FILE" >/dev/null
  pipeline_candidate_coverage_rc="$?"
  set -e
  if [ "$pipeline_candidate_coverage_rc" -eq 0 ]; then
    MONTHLY_PIPELINE_CANDIDATE_COVERAGE_STATUS="$(python3 - "$MONTHLY_PIPELINE_CANDIDATE_COVERAGE_FILE" <<'PY'
import json
import sys
from pathlib import Path
try:
    data = json.loads(Path(sys.argv[1]).read_text(encoding="utf-8"))
except Exception:
    data = {}
print(data.get("status") or "unknown")
PY
)"
  else
    MONTHLY_PIPELINE_CANDIDATE_COVERAGE_STATUS="failed"
    exit "$pipeline_candidate_coverage_rc"
  fi
fi
if [ "$SEND_OWNER_EMAILS" = "1" ] && [ "$MONTHLY_PIPELINE_CANDIDATE_COVERAGE_STATUS" != "ok" ]; then
  OWNER_EMAIL_SEND_BLOCKED_REASON="${OWNER_EMAIL_SEND_BLOCKED_REASON:-monthly active publish/Discord/email candidate coverage is not ok}"
fi


CURRENT_STEP="owner_email_send_guard"
refresh_owner_email_send_guard_report

if [ "$SEND_OWNER_EMAILS" = "1" ] \
  && [ "$SEND_NATIVE_LOFTY_OWNER_EMAILS" = "1" ] \
  && [ "$DRY_RUN" != "1" ] \
  && [ "$PUBLISH_LOFTY_PM_UPDATES" = "1" ] \
  && [ "$LOFTY_PM_PUBLISH_STATUS" = "ok" ] \
  && [ "$MONTHLY_DISCORD_PROPERTY_UPDATE_STATUS" = "ok" ] \
  && [ "$MONTHLY_PIPELINE_CANDIDATE_COVERAGE_STATUS" = "ok" ] \
  && [ "$MONTHLY_READINESS_OWNER_EMAIL_ALLOWED" = "1" ] \
  && [ "$OWNER_EMAIL_SEND_GUARD_STATUS" = "ok" ] \
  && [ "$OWNER_EMAIL_SEND_GUARD_SEND_ALLOWED" = "1" ] \
  && [ -z "$OWNER_EMAIL_SEND_BLOCKED_REASON" ]; then
  CURRENT_STEP="native_lofty_owner_email_send"
  OWNER_EMAIL_PUBLISH_ARGS=("${PUBLISH_ARGS[@]}")
  OWNER_EMAIL_PUBLISH_ARGS+=(
    --report "$LOFTY_PM_OWNER_EMAIL_SEND_FILE"
    --send-owner-emails
    --email-only
  )
  set +e
  LOFTY_ALLOW_NATIVE_OWNER_EMAIL_SIGNAL_ONLY=1 \
  LOFTY_OWNER_EMAIL_READINESS_ROOT="$ROOT" \
    $PY "$LOFTY_PM_PUBLISH_SCRIPT" "${OWNER_EMAIL_PUBLISH_ARGS[@]}" >/dev/null
  native_owner_email_rc="$?"
  set -e
  if [ "$native_owner_email_rc" -eq 0 ]; then
    NATIVE_OWNER_EMAIL_SEND_STATUS="sent"
  elif [ "$native_owner_email_rc" -eq 2 ]; then
    NATIVE_OWNER_EMAIL_SEND_STATUS="review"
    OWNER_EMAIL_SEND_BLOCKED_REASON="native Lofty owner email send did not complete cleanly"
    if [ "$OWNER_EMAIL_FAILURE_NONBLOCKING" != "1" ]; then
      exit "$native_owner_email_rc"
    fi
  else
    NATIVE_OWNER_EMAIL_SEND_STATUS="failed"
    OWNER_EMAIL_SEND_BLOCKED_REASON="native Lofty owner email send failed (rc=$native_owner_email_rc)"
    if [ "$OWNER_EMAIL_FAILURE_NONBLOCKING" != "1" ]; then
      exit "$native_owner_email_rc"
    fi
  fi
elif [ "$SEND_NATIVE_LOFTY_OWNER_EMAILS" != "1" ]; then
  NATIVE_OWNER_EMAIL_SEND_STATUS="skipped_disabled"
fi

if [ "$SEND_OWNER_EMAILS" = "1" ] \
  && [ "$SEND_NON_NATIVE_OWNER_EMAILS" = "1" ] \
  && [ "$REQUIRE_NATIVE_LOFTY_OWNER_EMAILS" != "1" ] \
  && [ "$DRY_RUN" != "1" ] \
  && [ "$PUBLISH_LOFTY_PM_UPDATES" = "1" ] \
  && [ "$LOFTY_PM_PUBLISH_STATUS" = "ok" ] \
  && [ "$MONTHLY_DISCORD_PROPERTY_UPDATE_STATUS" = "ok" ] \
  && [ "$MONTHLY_PIPELINE_CANDIDATE_COVERAGE_STATUS" = "ok" ] \
  && [ "$MONTHLY_READINESS_OWNER_EMAIL_ALLOWED" = "1" ] \
  && [ "$OWNER_EMAIL_SEND_GUARD_STATUS" = "ok" ] \
  && [ "$OWNER_EMAIL_SEND_GUARD_SEND_ALLOWED" = "1" ] \
  && [ -z "$OWNER_EMAIL_SEND_BLOCKED_REASON" ]; then
  CURRENT_STEP="non_native_owner_email_packet_send"
  run_non_native_owner_email_packet "send"
fi

run_owner_review_gate "monthly_owner_review_gate_post_publish"

CURRENT_STEP="owner_email_diagnostic"
if [ ! -f "$ROOT/scripts/lofty_owner_email_weekly.py" ]; then
  OWNER_EMAIL_STATUS="skipped_missing_script"
elif ! $PY "$ROOT/scripts/lofty_owner_email_weekly.py" --json --workspace "$ROOT" > "$EMAIL_DIAGNOSTIC_FILE"; then
  OWNER_EMAIL_STATUS="diagnostic_review"
  if [ "$OWNER_EMAIL_FAILURE_NONBLOCKING" != "1" ]; then
    exit 1
  fi
else
  OWNER_EMAIL_PENDING_COUNT="$($PY - "$EMAIL_DIAGNOSTIC_FILE" <<'PY'
import json
import sys
from pathlib import Path
print(int(json.loads(Path(sys.argv[1]).read_text(encoding="utf-8")).get("pending_property_count") or 0))
PY
)"
  if [ "$NATIVE_OWNER_EMAIL_SEND_STATUS" = "sent" ]; then
    OWNER_EMAIL_STATUS="sent_by_native_lofty_pm_mcp"
  elif [ "$SEND_OWNER_EMAILS" != "1" ]; then
    OWNER_EMAIL_SEND_BLOCKED_REASON="${OWNER_EMAIL_SEND_BLOCKED_REASON:-SEND_OWNER_EMAILS disabled}"
    OWNER_EMAIL_STATUS="skipped_disabled"
  elif [ "$DRY_RUN" = "1" ]; then
    OWNER_EMAIL_SEND_BLOCKED_REASON="${OWNER_EMAIL_SEND_BLOCKED_REASON:-dry run}"
    OWNER_EMAIL_STATUS="skipped_dry_run"
  elif [ "$LOFTY_PM_PUBLISH_STATUS" = "ok" ] && [ "$OWNER_EMAIL_SEND_REQUESTED" = "1" ]; then
    if [ "$SEND_NON_NATIVE_OWNER_EMAILS" != "1" ]; then
      OWNER_EMAIL_SEND_BLOCKED_REASON="${OWNER_EMAIL_SEND_BLOCKED_REASON:-non-native owner email packet send disabled}"
      OWNER_EMAIL_STATUS="skipped_non_native_owner_email_send_disabled"
    elif [ "$OWNER_EMAIL_SEND_GUARD_STATUS" != "ok" ]; then
      OWNER_EMAIL_SEND_BLOCKED_REASON="Owner email send guard did not pass after Lofty PM publish (status=$OWNER_EMAIL_SEND_GUARD_STATUS)"
      OWNER_EMAIL_STATUS="review_owner_email_send_guard"
      exit 1
    elif [ "$OWNER_EMAIL_PACKET_STATUS" != "ok" ]; then
      OWNER_EMAIL_SEND_BLOCKED_REASON="non-native owner email packet did not pass (status=$OWNER_EMAIL_PACKET_STATUS, issues=$OWNER_EMAIL_PACKET_ISSUE_COUNT)"
      OWNER_EMAIL_STATUS="review_non_native_owner_email_packet"
      exit 1
    elif [ "$OWNER_EMAIL_PACKET_SENT_STATE_WRITTEN" = "1" ]; then
      echo "$RUN_MONTH" > "$EMAIL_SENT_STATE_FILE"
      OWNER_EMAIL_STATUS="sent_by_non_native_owner_email_packet"
    else
      OWNER_EMAIL_SEND_BLOCKED_REASON="non-native owner email packet did not write sent state"
      OWNER_EMAIL_STATUS="review_non_native_owner_email_packet_sent_state"
      exit 1
    fi
  elif [ "$LOFTY_PM_PUBLISH_STATUS" = "ok" ] && [ -n "$OWNER_EMAIL_SEND_BLOCKED_REASON" ]; then
    OWNER_EMAIL_STATUS="skipped_${OWNER_EMAIL_SEND_BLOCKED_REASON//[^A-Za-z0-9]/_}"
  elif [ "$MONTHLY_READINESS_OWNER_EMAIL_ALLOWED" != "1" ]; then
    OWNER_EMAIL_SEND_BLOCKED_REASON="${OWNER_EMAIL_SEND_BLOCKED_REASON:-$(monthly_readiness_blocked_reason)}"
    OWNER_EMAIL_STATUS="blocked_by_monthly_readiness"
  elif [ "$MONTHLY_READINESS_STATUS" != "ok" ]; then
    OWNER_EMAIL_SEND_BLOCKED_REASON="${OWNER_EMAIL_SEND_BLOCKED_REASON:-monthly readiness status is $MONTHLY_READINESS_STATUS}"
    OWNER_EMAIL_STATUS="blocked_by_monthly_readiness"
  elif [ "$OWNER_EMAIL_PENDING_COUNT" -le 0 ]; then
    OWNER_EMAIL_SEND_BLOCKED_REASON="${OWNER_EMAIL_SEND_BLOCKED_REASON:-no pending owner emails}"
    OWNER_EMAIL_STATUS="skipped_no_pending"
  elif [ -f "$EMAIL_SENT_STATE_FILE" ] && [ "$(cat "$EMAIL_SENT_STATE_FILE" 2>/dev/null || true)" = "$RUN_MONTH" ]; then
    OWNER_EMAIL_SEND_BLOCKED_REASON="${OWNER_EMAIL_SEND_BLOCKED_REASON:-owner emails already sent for $RUN_MONTH}"
    OWNER_EMAIL_STATUS="skipped_already_sent_this_month"
  elif [ "$RUN_LEGACY_OWNER_EMAIL_WEEKLY" != "1" ]; then
    OWNER_EMAIL_SEND_BLOCKED_REASON="${OWNER_EMAIL_SEND_BLOCKED_REASON:-legacy weekly sender disabled}"
    OWNER_EMAIL_STATUS="skipped_legacy_weekly_sender_disabled"
  elif [ "$OWNER_EMAIL_SEND_GUARD_STATUS" != "ok" ] || [ "$OWNER_EMAIL_SEND_GUARD_SEND_ALLOWED" != "1" ]; then
    OWNER_EMAIL_SEND_BLOCKED_REASON="${OWNER_EMAIL_SEND_BLOCKED_REASON:-legacy weekly sender refused because owner email send guard did not explicitly allow send (status=$OWNER_EMAIL_SEND_GUARD_STATUS, send_allowed=$OWNER_EMAIL_SEND_GUARD_SEND_ALLOWED)}"
    OWNER_EMAIL_STATUS="blocked_by_owner_email_send_guard"
    exit 1
  else
    CURRENT_STEP="owner_email_send"
    LOFTY_OWNER_UPDATE_SEND_INTERVAL_DAYS="$OWNER_EMAIL_INTERVAL_DAYS" \
      $PY "$ROOT/scripts/lofty_owner_email_weekly.py" --send-interval-days "$OWNER_EMAIL_INTERVAL_DAYS"
    echo "$RUN_MONTH" > "$EMAIL_SENT_STATE_FILE"
    OWNER_EMAIL_STATUS="sent"
  fi
fi

CURRENT_STEP="complete"
